INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('99','en','Life and Time Management Training','TİMDER members met at the Istanbul Dedeman Hotel for the “Life and Time Management” training. The training, delivered by our trainer Cemal Bozkurt, attracted intense interest. We thank everyone who attended. Hoping to meet again at new trainings...','<p>TİMDER members met at the Istanbul Dedeman Hotel for the “Life and Time Management” training. The training, delivered by our trainer Cemal Bozkurt, attracted intense interest. We thank everyone who attended. Hoping to meet again at new trainings...</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('99','de','Schulung „Lebens- und Zeitmanagement“','Die TİMDER-Mitglieder trafen sich im Dedeman Hotel Istanbul zur Schulung „Lebens- und Zeitmanagement“. Die von unserem Trainer Cemal Bozkurt gegebene Schulung stieß auf großes Interesse. Wir danken allen Teilnehmenden. Auf ein Wiedersehen bei neuen Schulungen...','<p>Die TİMDER-Mitglieder trafen sich im Dedeman Hotel Istanbul zur Schulung „Lebens- und Zeitmanagement“. Die von unserem Trainer Cemal Bozkurt gegebene Schulung stieß auf großes Interesse. Wir danken allen Teilnehmenden. Auf ein Wiedersehen bei neuen Schulungen...</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('100','en','Sales Management and Sales Techniques Training','Sales and sales management — one of the most important strategic topics of the business world — has gained more importance than ever, both individually and at company level. Those wishing to develop themselves in this field met on Tuesday, 25 September at the Istanbul Dedeman Hotel within TİMDER Academy. The core title of the training, given by the esteemed trainer Hakan Metin Akgün, was “Sales Management and Sales Techniques”. We wish everyone who attended success, and hope to meet at new trainings.','<p>Sales and sales management — one of the most important strategic topics of the business world — has gained more importance than ever, both individually and at company level. Those wishing to develop themselves in this field met on Tuesday, 25 September at the Istanbul Dedeman Hotel within TİMDER Academy. The core title of the training, given by the esteemed trainer Hakan Metin Akgün, was “Sales Management and Sales Techniques”. We wish everyone who attended success, and hope to meet at new trainings.</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('100','de','Schulung „Vertriebsmanagement und Verkaufstechniken“','Vertrieb und Vertriebsmanagement — eines der wichtigsten Strategiethemen der Geschäftswelt — hat heute individuell wie auf Unternehmensebene mehr Bedeutung denn je. Wer sich auf diesem Gebiet weiterentwickeln wollte, traf sich am Dienstag, dem 25. September, im Rahmen der TİMDER-Akademie im Dedeman Hotel Istanbul. Der Kerntitel der vom geschätzten Trainer Hakan Metin Akgün gegebenen Schulung lautete „Vertriebsmanagement und Verkaufstechniken“. Wir wünschen allen Teilnehmenden Erfolg und hoffen, uns bei neuen Schulungen wiederzusehen.','<p>Vertrieb und Vertriebsmanagement — eines der wichtigsten Strategiethemen der Geschäftswelt — hat heute individuell wie auf Unternehmensebene mehr Bedeutung denn je. Wer sich auf diesem Gebiet weiterentwickeln wollte, traf sich am Dienstag, dem 25. September, im Rahmen der TİMDER-Akademie im Dedeman Hotel Istanbul. Der Kerntitel der vom geschätzten Trainer Hakan Metin Akgün gegebenen Schulung lautete „Vertriebsmanagement und Verkaufstechniken“. Wir wünschen allen Teilnehmenden Erfolg und hoffen, uns bei neuen Schulungen wiederzusehen.</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('101','en','Effective Communication Techniques Training','Being able to express ourselves correctly, with awareness in communication, provides us many advantages both in business and in social life. For this reason, together with TİMDER Academy, we delivered the “Effective Communication Techniques” training with trainer Sibel Özpulat on 20 September 2018 at the Dedeman Hotel / Gayrettepe.','<p>Being able to express ourselves correctly, with awareness in communication, provides us many advantages both in business and in social life. For this reason, together with TİMDER Academy, we delivered the “Effective Communication Techniques” training with trainer Sibel Özpulat on 20 September 2018 at the Dedeman Hotel / Gayrettepe.</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('101','de','Schulung „Wirksame Kommunikationstechniken“','Sich mit Bewusstsein in der Kommunikation richtig ausdrücken zu können, verschafft uns im Berufs- wie im Sozialleben viele Vorteile. Deshalb haben wir gemeinsam mit der TİMDER-Akademie am 20. September 2018 im Dedeman Hotel / Gayrettepe die Schulung „Wirksame Kommunikationstechniken“ mit der Trainerin Sibel Özpulat durchgeführt.','<p>Sich mit Bewusstsein in der Kommunikation richtig ausdrücken zu können, verschafft uns im Berufs- wie im Sozialleben viele Vorteile. Deshalb haben wir gemeinsam mit der TİMDER-Akademie am 20. September 2018 im Dedeman Hotel / Gayrettepe die Schulung „Wirksame Kommunikationstechniken“ mit der Trainerin Sibel Özpulat durchgeführt.</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('102','en','Sales Trends and Creative Selling Training','Though they look the same at heart, sales trends are changing at an incredible pace. To keep up with all this, we opened TİMDER Academy\'s 2018 season on Tuesday evening, 18 September at the Dedeman Hotel / Gayrettepe with Dr. Zeki Yüksekbilgili\'s “Sales Trends and Creative Selling” training.','<p>Though they look the same at heart, sales trends are changing at an incredible pace. To keep up with all this, we opened TİMDER Academy\'s 2018 season on Tuesday evening, 18 September at the Dedeman Hotel / Gayrettepe with Dr. Zeki Yüksekbilgili\'s “Sales Trends and Creative Selling” training.</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('102','de','Schulung „Verkaufstrends und kreatives Verkaufen“','Auch wenn sie im Kern gleich erscheinen, ändern sich die Verkaufstrends in unglaublichem Tempo. Um damit Schritt zu halten, eröffneten wir die Saison 2018 der TİMDER-Akademie am Dienstagabend, dem 18. September, im Dedeman Hotel / Gayrettepe mit der Schulung „Verkaufstrends und kreatives Verkaufen“ von Dr. Zeki Yüksekbilgili.','<p>Auch wenn sie im Kern gleich erscheinen, ändern sich die Verkaufstrends in unglaublichem Tempo. Um damit Schritt zu halten, eröffneten wir die Saison 2018 der TİMDER-Akademie am Dienstagabend, dem 18. September, im Dedeman Hotel / Gayrettepe mit der Schulung „Verkaufstrends und kreatives Verkaufen“ von Dr. Zeki Yüksekbilgili.</p>',NULL,'1');
