INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('127','de','Seminar „Führung in der neuen Welt“','Mit dem Seminar „Führung in der neuen Welt“ wurden den Teilnehmenden verschiedene Führungsmodelle, moderne Managementpraktiken und das nötige Wissen für wirksame Führung vermittelt.','<p>Mit dem Seminar „Führung in der neuen Welt“ wurden den Teilnehmenden verschiedene Führungsmodelle, moderne Managementpraktiken und das nötige Wissen für wirksame Führung vermittelt.</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('128','en','Private Public Bus and İETT Trainings','In cooperation with the Private Public Bus Operators and the İETT General Directorate, we carry out training activities for bus drivers at İETT\'s training centers with our team of expert trainers. The trainings have been defined under the main headings of Traffic Knowledge and Culture, Public Transport Operations in Cities, Public Relations, Human Behavior, Empathy, Psychotechnics, Stress Management and Anger Control.','<p>In cooperation with the Private Public Bus Operators and the İETT General Directorate, we carry out training activities for bus drivers at İETT\'s training centers with our team of expert trainers. The trainings have been defined under the main headings of Traffic Knowledge and Culture, Public Transport Operations in Cities, Public Relations, Human Behavior, Empathy, Psychotechnics, Stress Management and Anger Control.</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('128','de','Schulungen für private Stadtbusse und İETT','In Zusammenarbeit mit den Betreibern privater Stadtbusse und der İETT-Generaldirektion führen wir mit unserem Team fachkundiger Trainer Schulungen für Busfahrer in den Schulungszentren der İETT durch. Die Schulungen umfassen die Hauptthemen Verkehrswissen und -kultur, ÖPNV-Betrieb in Städten, Öffentlichkeitsarbeit, menschliches Verhalten, Empathie, Psychotechnik, Stressbewältigung und Wutkontrolle.','<p>In Zusammenarbeit mit den Betreibern privater Stadtbusse und der İETT-Generaldirektion führen wir mit unserem Team fachkundiger Trainer Schulungen für Busfahrer in den Schulungszentren der İETT durch. Die Schulungen umfassen die Hauptthemen Verkehrswissen und -kultur, ÖPNV-Betrieb in Städten, Öffentlichkeitsarbeit, menschliches Verhalten, Empathie, Psychotechnik, Stressbewältigung und Wutkontrolle.</p>',NULL,'1');
