INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('136','en','Profitability Control for Bosses Training','At the seminar, which drew strong attendance from company owners, Prof. Dr. Burak Arzova explained — with practical examples — cash flow from a profitability perspective, the factors affecting cost, and the strategic steps in building a budget.','<p>At the seminar, which drew strong attendance from company owners, Prof. Dr. Burak Arzova explained — with practical examples — cash flow from a profitability perspective, the factors affecting cost, and the strategic steps in building a budget.</p>',NULL,'1');
INSERT IGNORE INTO `tablo_haberler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`KisaBilgi`,`Detay`,`Kategori`,`YayinDurumu`) VALUES ('136','de','Schulung „Rentabilitätskontrolle für Unternehmenschefs“','Bei dem von Unternehmenschefs stark besuchten Seminar erläuterte Prof. Dr. Burak Arzova anhand praktischer Beispiele den Cashflow aus Rentabilitätssicht, die kostenbeeinflussenden Faktoren und die strategischen Schritte bei der Budgeterstellung.','<p>Bei dem von Unternehmenschefs stark besuchten Seminar erläuterte Prof. Dr. Burak Arzova anhand praktischer Beispiele den Cashflow aus Rentabilitätssicht, die kostenbeeinflussenden Faktoren und die strategischen Schritte bei der Budgeterstellung.</p>',NULL,'1');
