INSERT IGNORE INTO `tablo_danismanlar_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Unvan`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`YayinDurumu`) VALUES ('28','de','Tuğba Güner','Projektdirektorin','+90 (212) 465 03 77-78 / Durchwahl 118','tguner@organikik.com','<h6>Wirtschaftsingenieurwesen</h6><p>Master of Business Administration (MBA)<br></p>',NULL,'<ul><li>Strategieberatung</li><li>Beratung für Unternehmensentwicklung</li><li>Personalberatung</li><li>Ganzheitliche Qualitätsberatung</li><li>EFQM-Beratung</li><li>Projektmanagement-Beratung</li><li>Produktmanagement-Beratung</li><li>Öffentliche Dienstleistungen</li></ul>','<ul><li>Eltemtek – TEİAŞ – Personalbedarfsplanung</li><li>Eltemtek – TEİAŞ – Schulungsmanagementsystem</li><li>Eltemtek – TEİAŞ – Innovationsmanagementsystem</li><li>Eltemtek – TEİAŞ – Prozessmanagement</li><li>Eltemtek – TEİAŞ – Kundenbeziehungsmanagement</li><li>Eltemtek – TEİAŞ – Individuelles Leistungsmanagement</li><li>Eltemtek – NDK – Strategischer Plan</li><li>Eltemtek – NDK – Schulungsmanagementsystem</li><li>Eltemtek – NDK – Personalbedarfsplanung</li><li>Eltemtek – NDK – Mitarbeiterzufriedenheitsstudie</li><li>Eltemtek – NDK – Stakeholder-Zufriedenheitsstudie</li><li>TPIC – Personalbedarfsplanung</li><li>TPIC – Karriereplanungssystem</li></ul>','1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('1','en','Corporate Development Consultancy','CORPORATE <br> DEVELOPMENT <br><span>CONSULTANCY</span>','<p>In its simplest form, institutionalization means systematizing all activities of a business and freeing it from dependence on individuals. The institutionalization process is a structure that is open to continuous improvement and always has new areas to be completed.</p>','<p>Corporate development, in turn, is the whole of the work carried out during institutionalization to identify problems and their root causes and to solve them, with the aim of increasing companies\' performance in growth, profitability, people management, competition, adaptation and continuity.</p>','<p>Institutionalization;</p>','<p>• Makes it possible to look at the business as a whole.</p>\r\n<p>• Supports corporate culture by bringing all employees together around a shared vision.</p>\r\n<p>• Ensures sustainability in ongoing activities/operations and in the company\'s growth.</p>','<p>• Reduces dependence on individuals and strengthens corporate memory.</p>\r\n<p>• Reveals the causes of problems encountered and develops solution proposals.</p>\r\n<p>• Increases adaptability to change.</p>\r\n<p>As Organik Consulting Services, the services we offer businesses in the field of corporate development are;</p>','<p><span>Organizational Improvement</span></p>\r\n<p><span>Corporate Development Plan</span></p>\r\n<p><span>Restructuring</span></p>\r\n<p><span>Corporate Performance Management</span></p>\r\n<p><span>Corporate Check-Up</span></p>','<p>Tools: Business Analysis, Job Analysis, Process Analysis, SWOT and PESTLE Analysis, Interviews, Focus Groups, Workshops</p>','<h4>Organizational <br>Improvement</h4>\r\n<p>Starting with an analysis of the current structure of the business, it is the process of reaching the targeted structure by enabling the business to make the best use of its organizational capabilities so that it can carry out its sector activities more efficiently, use its resources more effectively and keep its processes running without interruption.</p>\r\n<p>Organizational Improvement;</p>\r\n<ul>\r\n<li>· Reveals the organizational problems in the current situation.</li>\r\n<li>· Improves the ability to carry out activities.</li>\r\n<li>· Works to obtain maximum benefit from available resources.</li>\r\n<li>· Creates the environment required for business processes to run without interruption.</li>\r\n<li>· Ensures the most appropriate use of the organizational capabilities that will develop the business.</li>\r\n</ul>','<h4>Corporate <br> Development Plan</h4>\r\n<p>Drawing strength from the company\'s mission, vision and core values, it is the planning required to enable the company to take the right forward-looking decisions, to implement the strategic decisions effectively and to develop in the direction needed by managing all its resources correctly. The corporate development plan covers the process of systematically bringing together function-based work so that the company can reach the point it aims for.</p>\r\n<p>The Corporate Development Plan;</p>\r\n<ul>\r\n<li>· Reveals the current situation and needs through analysis studies.</li>\r\n<li>· Supports the planning of future steps.</li>\r\n<li>· Identifies the systems required to realize the goals set for the future and the decisions taken.</li>\r\n<li>· Ensures effective use of resources.</li>\r\n<li>· Contributes at the highest level to keeping the company sustainable in working order.</li>\r\n<li>· Supports continuous improvement by encouraging a monitoring and evaluation system.</li>\r\n</ul>','<h4>Restructuring <br> (Reorganization)</h4>\r\n<p>Restructuring (reorganization) is the whole of the planned work carried out to serve the company\'s purpose of existence by redesigning an organizational structure that has become inadequate in the face of internal and external factors and making it as effective as possible.</p>\r\n<p>Restructuring;</p>\r\n<ul>\r\n<li>· Increases the company\'s resilience in the competitive environment.</li>\r\n<li>· Eliminates problems and communication breakdowns in areas of shared responsibility.</li>\r\n<li>· Identifies and improves idle areas and areas of need open to development.</li>\r\n<li>· Increases efficiency in the distribution of tasks and in the organizational structure.</li>\r\n<li>· Improves the organization\'s ability to get work done.</li>\r\n</ul>','<h4>Corporate <br> Performance Management</h4>\r\n<p>Corporate performance management is the execution of performance monitoring, measurement and evaluation processes to ensure effective corporate performance while achieving the company goals set in line with the mission and vision.</p>\r\n<p>The balanced scorecard is used as a tool in measuring and monitoring corporate performance. The balanced scorecard is an approach that aims to translate the company vision and strategies into operations. Strategies are translated into goals, and goals into perspectives. To develop long-term strategies, customer, internal process, learning and growth indicators should be used alongside financial indicators. In this context, the balanced scorecard consists of four perspectives.</p>\r\n<p>The Balanced Scorecard;</p>\r\n<ul>\r\n<li>· Makes it easier for all units of the company to understand and align with the strategies.</li>\r\n<li>· Creates awareness of future goals and actions.</li>\r\n<li>· Facilitates the transfer of vision and strategies among stakeholders.</li>\r\n<li>· Evaluates the company objectively and from different dimensions.</li>\r\n<li>· Supports continuous improvement by activating the follow-up mechanism.</li>\r\n</ul>','<h4>Corporate <br> Check-Up</h4>\r\n<p>The biggest obstacle to institutionalization is not knowing the level of institutionalization and, consequently, the needs required for it. The corporate check-up is a professional methodology that measures the company\'s level of institutionalization in different areas, identifies its future risks and reveals its institutionalization needs, enabling a road map to be created.</p>\r\n<p>The Corporate Check-Up;</p>\r\n<ul>\r\n<li>· Reveals the company\'s level of institutionalization.</li>\r\n<li>· Identifies the needs required for institutionalization.</li>\r\n<li>· Creates the road map for meeting those needs.</li>\r\n<li>· Provides benchmarking that shows progress.</li>\r\n</ul>','Organizational Improvement','Corporate Development Plan','Restructuring (Reorganization)','Corporate Performance Management','Corporate Check-Up','1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('1','de','Beratung für Unternehmensentwicklung','BERATUNG FÜR <br> UNTERNEHMENS-<br><span>ENTWICKLUNG</span>','<p>Institutionalisierung bedeutet in ihrer einfachsten Form, alle Tätigkeiten eines Unternehmens zu systematisieren und von der Abhängigkeit von einzelnen Personen zu befreien. Der Institutionalisierungsprozess ist eine Struktur, die kontinuierlicher Weiterentwicklung offensteht und stets neue zu vervollständigende Bereiche aufweist.</p>','<p>Unternehmensentwicklung wiederum ist die Gesamtheit der Arbeiten zur Ermittlung von Problemen und ihren Ursachen sowie zu deren Lösung während der Institutionalisierung — mit dem Ziel, die Leistung der Unternehmen in Wachstum, Rentabilität, Personalführung, Wettbewerb, Anpassung und Kontinuität zu steigern.</p>','<p>Institutionalisierung;</p>','<p>• Ermöglicht es, das Unternehmen als Ganzes zu betrachten.</p>\r\n<p>• Unterstützt die Unternehmenskultur, indem sie alle Mitarbeitenden unter einer gemeinsamen Vision zusammenführt.</p>\r\n<p>• Gewährleistet Nachhaltigkeit in den laufenden Tätigkeiten/Abläufen und im Wachstum des Unternehmens.</p>','<p>• Verringert die Abhängigkeit von Einzelpersonen und stärkt das Unternehmensgedächtnis.</p>\r\n<p>• Deckt die Ursachen auftretender Probleme auf und entwickelt Lösungsvorschläge.</p>\r\n<p>• Erhöht die Anpassungsfähigkeit an Veränderungen.</p>\r\n<p>Als Organik Beratungsdienstleistungen bieten wir Unternehmen im Bereich Unternehmensentwicklung folgende Leistungen an;</p>','<p><span>Organisatorische Verbesserung</span></p>\r\n<p><span>Unternehmensentwicklungsplan</span></p>\r\n<p><span>Neustrukturierung</span></p>\r\n<p><span>Unternehmens-Leistungsmanagement</span></p>\r\n<p><span>Unternehmens-Check-up</span></p>','<p>Instrumente: Unternehmensanalyse, Arbeitsanalyse, Prozessanalyse, SWOT- und PESTLE-Analyse, Interviews, Fokusgruppen, Workshops</p>','<h4>Organisatorische <br>Verbesserung</h4>\r\n<p>Beginnend mit der Analyse der bestehenden Struktur des Unternehmens geht es darum, die Zielstruktur zu erreichen, indem das Unternehmen seine organisatorischen Fähigkeiten bestmöglich einsetzt — damit es seine Branchentätigkeiten effizienter ausführt, seine Ressourcen wirksamer nutzt und seine Prozesse unterbrechungsfrei ablaufen.</p>\r\n<p>Organisatorische Verbesserung;</p>\r\n<ul>\r\n<li>· Deckt die organisatorischen Probleme der Ist-Situation auf.</li>\r\n<li>· Verbessert die Fähigkeit zur Durchführung der Tätigkeiten.</li>\r\n<li>· Arbeitet auf den maximalen Nutzen der vorhandenen Ressourcen hin.</li>\r\n<li>· Schafft das erforderliche Umfeld für unterbrechungsfreie Geschäftsprozesse.</li>\r\n<li>· Stellt den richtigen Einsatz der organisatorischen Fähigkeiten sicher, die das Unternehmen weiterentwickeln.</li>\r\n</ul>','<h4>Unternehmens-<br>entwicklungsplan</h4>\r\n<p>Gestützt auf Mission, Vision und Grundwerte des Unternehmens werden die erforderlichen Planungen vorgenommen, damit das Unternehmen die richtigen zukunftsgerichteten Entscheidungen trifft, die getroffenen strategischen Entscheidungen wirksam umsetzt und sich durch das richtige Management aller Ressourcen in die benötigte Richtung entwickelt. Der Unternehmensentwicklungsplan umfasst den Prozess, funktionsbezogene Arbeiten systematisch zusammenzuführen, damit das Unternehmen sein Ziel erreicht.</p>\r\n<p>Der Unternehmensentwicklungsplan;</p>\r\n<ul>\r\n<li>· Ermittelt durch Analysearbeiten die Ist-Situation und den Bedarf.</li>\r\n<li>· Unterstützt die Planung künftiger Schritte.</li>\r\n<li>· Bestimmt die Systeme, die zur Umsetzung der Zukunftsziele und Entscheidungen erforderlich sind.</li>\r\n<li>· Gewährleistet den wirksamen Einsatz der Ressourcen.</li>\r\n<li>· Trägt maximal zur nachhaltigen Funktionsfähigkeit des Unternehmens bei.</li>\r\n<li>· Fördert die kontinuierliche Verbesserung durch ein Monitoring- und Bewertungssystem.</li>\r\n</ul>','<h4>Neustrukturierung <br> (Reorganisation)</h4>\r\n<p>Die Neustrukturierung (Reorganisation) ist die Gesamtheit der planmäßigen Arbeiten, mit denen eine gegenüber internen und externen Faktoren unzureichend gewordene Organisationsstruktur neu geordnet und so wirksam wie möglich gestaltet wird, um dem Daseinszweck des Unternehmens zu dienen.</p>\r\n<p>Neustrukturierung;</p>\r\n<ul>\r\n<li>· Erhöht die Widerstandsfähigkeit des Unternehmens im Wettbewerbsumfeld.</li>\r\n<li>· Beseitigt Probleme und Kommunikationsstörungen in gemeinsamen Verantwortungsbereichen.</li>\r\n<li>· Erkennt und verbessert brachliegende und entwicklungsfähige Bedarfsbereiche.</li>\r\n<li>· Steigert die Effizienz bei der Aufgabenverteilung und in der Organisationsstruktur.</li>\r\n<li>· Verbessert die organisatorische Arbeitsfähigkeit.</li>\r\n</ul>','<h4>Unternehmens-<br>Leistungsmanagement</h4>\r\n<p>Unternehmens-Leistungsmanagement ist die Durchführung von Prozessen zur Leistungsüberwachung, -messung und -bewertung, um beim Erreichen der im Einklang mit Mission und Vision festgelegten Unternehmensziele eine wirksame Unternehmensleistung sicherzustellen.</p>\r\n<p>Zur Messung und Verfolgung der Unternehmensleistung wird die Balanced Scorecard als Instrument eingesetzt. Die Balanced Scorecard ist ein Ansatz, der Vision und Strategien des Unternehmens in operative Tätigkeiten übersetzen will. Strategien werden in Ziele und Ziele in Perspektiven übersetzt. Für langfristige Strategien sollten neben Finanzkennzahlen auch Kennzahlen zu Kunden, internen Prozessen sowie Lernen und Entwicklung herangezogen werden. In diesem Zusammenhang besteht die Balanced Scorecard aus vier Perspektiven.</p>\r\n<p>Die Balanced Scorecard;</p>\r\n<ul>\r\n<li>· Erleichtert allen Unternehmensbereichen das Verständnis der Strategien und die Ausrichtung darauf.</li>\r\n<li>· Schafft Bewusstsein für Zukunftsziele und Maßnahmen.</li>\r\n<li>· Erleichtert die Vermittlung von Vision und Strategien unter den Stakeholdern.</li>\r\n<li>· Bewertet das Unternehmen objektiv und aus verschiedenen Dimensionen.</li>\r\n<li>· Unterstützt die kontinuierliche Verbesserung durch Aktivierung des Nachverfolgungsmechanismus.</li>\r\n</ul>','<h4>Unternehmens-<br>Check-up</h4>\r\n<p>Das größte Hindernis für die Institutionalisierung ist die Unkenntnis des Institutionalisierungsgrads und damit des dafür erforderlichen Bedarfs. Der Unternehmens-Check-up ist eine professionelle Methodik, die den Institutionalisierungsgrad des Unternehmens in verschiedenen Bereichen misst, seine Zukunftsrisiken bestimmt und den Institutionalisierungsbedarf aufzeigt, sodass ein Fahrplan erstellt werden kann.</p>\r\n<p>Der Unternehmens-Check-up;</p>\r\n<ul>\r\n<li>· Zeigt den Institutionalisierungsgrad des Unternehmens auf.</li>\r\n<li>· Bestimmt den für die Institutionalisierung erforderlichen Bedarf.</li>\r\n<li>· Erstellt den Fahrplan zur Deckung des Bedarfs.</li>\r\n<li>· Ermöglicht Vergleiche, die den Fortschritt sichtbar machen.</li>\r\n</ul>','Organisatorische Verbesserung','Unternehmensentwicklungsplan','Neustrukturierung (Reorganisation)','Unternehmens-Leistungsmanagement','Unternehmens-Check-up','1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('2','en','Strategy Consultancy','STRATEGY <br><span>CONSULTANCY</span>','<p><b>Strategy is used to create a focal point, alignment, harmony and purpose for an organization by developing the plans, maneuvers, models, positions and perspectives that will guide strategic action.</b></p>','<p>In today\'s businesses, it means developing the strategies and methods that will deliver the best service to society in the most efficient and effective way, and thus achieving goals and objectives. In a rapidly changing world, businesses can keep pace with these changes only by having a long-term vision and by defining and implementing the necessary strategies from this long-term perspective.</p>\r\n<p>Strategic management is the name of the systematic approach through which strategic thinking, and the philosophy behind it, is brought to life. This approach is a process involving certain stages. Strategic management and the strategic management process are about reaching decisions on what the business should do and where it should go.</p>','<p>Strategic Management;</p>','','<p>• Allows businesses to notice changing conditions in advance.</p>\r\n<p>• Provides clear goals and direction.</p>\r\n<p>• Helps managers investigate the fundamental problems of the business.</p>\r\n<p>• Work that implements strategic management is more effective.</p>\r\n<p>• Makes business decisions systematic.</p>\r\n<p>• Helps the business\'s communication, the coordination of individual projects, the allocation of resources and the development of short-term planning such as budgeting.</p>','<p>As Organik Consulting Services, the services we offer businesses in strategic management are;</p>\r\n<p><span>Strategic Planning</span></p>\r\n<p><span>Strategy Mapping</span></p>\r\n<p><span>Value Chain Management</span></p>\r\n<p><span>Future-Focused Planning</span></p>','<p>Tools: Business Analysis, Job Analysis, SWOT and PESTLE Analysis, Interviews, Focus Groups</p>','<h4>Strategic <br>Planning</h4>\r\n<p>It offers businesses the opportunity to think long term, to identify strategically important issues and to focus on these areas in order to achieve sustainable success. It is the definition of strategic goals and objectives that will increase the business\'s strategic competitiveness, and of the activities that will realize them. Strategic planning covers all result-oriented efforts, involving the participation of employees at every level and the full support of the business\'s management.</p>\r\n<p>Strategic Planning;</p>\r\n<ul>\r\n<li>· Enables the business to know itself through analysis of the current structure.</li>\r\n<li>· Identifies the strengths and weaknesses of the business and the opportunities and threats facing it.</li>\r\n<li>· Ensures that strategic goals and objectives are defined.</li>\r\n<li>· Reveals the activities required to achieve the objectives.</li>\r\n<li>· Allows objectives to be monitored continuously through performance programs built around objectives broken down to unit level.</li>\r\n<li>· Enables continuous development by having objectives reviewed according to monitoring and evaluation results.</li>\r\n<li>· Creates the mission and vision for the business, supporting all units and employees in working toward common goals.</li>\r\n</ul>','<h4>Strategy <br> Mapping</h4>\r\n<p>It shows the connection structure of strategic goals and objectives with their actors, and their relationship with the modes required for implementation. It brings the growth and productivity qualities of the business to the fore.</p>\r\n<p>Strategy Mapping;</p>\r\n<ul>\r\n<li>· Offers a planning system by setting out the company\'s past, its vision for the future and the plans it will implement to reach the goals in that vision.</li>\r\n<li>· Takes the steps of the targeted strategic decisions and processes from the abstract to the concrete.</li>\r\n<li>· Conveys the strategic structure and objectives to the company\'s employees and stakeholders.</li>\r\n<li>· Creates a successful and sustainable strategic development process.</li>\r\n<li>· Makes activities and indicators aimed at the strategic goal trackable.</li>\r\n</ul>','<h4>Value Chain <br> Management</h4>\r\n<p>It is the planning of resources in line with the business\'s goals and the beneficial management of value-adding activities.</p>\r\n<p>Value Chain Management;</p>\r\n<ul>\r\n<li>· Determines the importance of the core and support activities in the business\'s service area.</li>\r\n<li>· Ensures processes progress in order of importance and action.</li>\r\n<li>· Shows which area of activity should be focused on.</li>\r\n</ul>','<h4>Future-Focused <br> Planning</h4>\r\n<p>Within the business\'s strategic management system, it is the planning of future goals in line with its mission, vision and core values.</p>\r\n<p>Future-Focused Planning;</p>\r\n<ul>\r\n<li>· Enables the business to look at the future more holistically and strategically.</li>\r\n<li>· Guides the actions to be taken.</li>\r\n<li>· Enables future goals to be planned within the business and their realization to be tracked.</li>\r\n<li>· Makes strategic success sustainable.</li>\r\n</ul>','<p><br></p>','Strategic Planning','Strategy Mapping','Value Chain Management','Future-Focused Planning',NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('2','de','Strategieberatung','STRATEGIE-<br><span>BERATUNG</span>','<p><b>Strategie dient dazu, für eine Organisation einen Fokus, Ausrichtung, Zusammenhalt und Sinn zu schaffen, indem Pläne, Manöver, Modelle, Positionen und Perspektiven entwickelt werden, die das strategische Handeln leiten.</b></p>','<p>In heutigen Unternehmen bedeutet dies, Strategien und Methoden zu entwickeln, mit denen der Gesellschaft die beste Leistung auf effizienteste und wirksamste Weise geboten wird — und so Ziele und Vorgaben zu erreichen. In einer sich rasant wandelnden Welt können Unternehmen nur Schritt halten, wenn sie über eine langfristige Vision verfügen und aus dieser langfristigen Perspektive die erforderlichen Strategien festlegen und umsetzen.</p>\r\n<p>Strategisches Management ist der Name des systematischen Ansatzes, mit dem strategisches Denken und die dahinterstehende Philosophie gelebt werden. Dieser Ansatz ist ein Prozess mit bestimmten Phasen. Strategisches Management und der strategische Managementprozess betreffen Entscheidungen darüber, was das Unternehmen tun und wohin es sich entwickeln soll.</p>','<p>Strategisches Management;</p>','','<p>• Ermöglicht es Unternehmen, sich verändernde Bedingungen frühzeitig zu erkennen.</p>\r\n<p>• Gibt klare Ziele und Orientierung.</p>\r\n<p>• Hilft Führungskräften, die grundlegenden Probleme des Unternehmens zu untersuchen.</p>\r\n<p>• Tätigkeiten mit strategischem Management sind wirksamer.</p>\r\n<p>• Systematisiert Geschäftsentscheidungen.</p>\r\n<p>• Unterstützt die Kommunikation des Unternehmens, die Koordination einzelner Projekte, die Ressourcenzuteilung und die Entwicklung kurzfristiger Planungen wie des Budgets.</p>','<p>Als Organik Beratungsdienstleistungen bieten wir Unternehmen im strategischen Management folgende Leistungen an;</p>\r\n<p><span>Strategische Planung</span></p>\r\n<p><span>Strategy Mapping</span></p>\r\n<p><span>Wertschöpfungskettenmanagement</span></p>\r\n<p><span>Zukunftsorientierte Planung</span></p>','<p>Instrumente: Unternehmensanalyse, Arbeitsanalyse, SWOT- und PESTLE-Analyse, Interviews, Fokusgruppen</p>','<h4>Strategische <br>Planung</h4>\r\n<p>Sie bietet Unternehmen die Möglichkeit, langfristig zu denken, strategisch wichtige Themen zu erkennen und sich auf diese Bereiche zu konzentrieren, um nachhaltigen Erfolg zu sichern. Es werden strategische Ziele und Vorgaben festgelegt, die die strategische Wettbewerbsfähigkeit steigern, sowie die Maßnahmen zu deren Umsetzung bestimmt. Die strategische Planung umfasst alle ergebnisorientierten Anstrengungen unter Beteiligung der Mitarbeitenden aller Ebenen und mit voller Unterstützung der Unternehmensleitung.</p>\r\n<p>Strategische Planung;</p>\r\n<ul>\r\n<li>· Ermöglicht dem Unternehmen durch Analyse der bestehenden Struktur, sich selbst kennenzulernen.</li>\r\n<li>· Bestimmt Stärken und Schwächen des Unternehmens sowie Chancen und Risiken.</li>\r\n<li>· Sorgt für die Festlegung strategischer Ziele und Vorgaben.</li>\r\n<li>· Zeigt die zur Zielerreichung erforderlichen Maßnahmen auf.</li>\r\n<li>· Ermöglicht durch bis auf Abteilungsebene heruntergebrochene Ziele und zugehörige Leistungsprogramme deren laufende Überwachung.</li>\r\n<li>· Erlaubt kontinuierliche Weiterentwicklung, indem Ziele anhand der Monitoring- und Bewertungsergebnisse überprüft werden.</li>\r\n<li>· Schafft Mission und Vision für das Unternehmen und unterstützt alle Bereiche und Mitarbeitenden dabei, auf gemeinsame Ziele hinzuarbeiten.</li>\r\n</ul>','<h4>Strategy <br> Mapping</h4>\r\n<p>Es zeigt die Verknüpfung der strategischen Ziele und Vorgaben mit ihren Akteuren sowie ihre Beziehung zu den für die Umsetzung erforderlichen Wegen. Die Wachstums- und Produktivitätsmerkmale des Unternehmens werden in den Vordergrund gestellt.</p>\r\n<p>Strategy Mapping;</p>\r\n<ul>\r\n<li>· Bietet ein Planungssystem, das die Vergangenheit des Unternehmens, seine Zukunftsvision und die Pläne zur Erreichung der Visionsziele darlegt.</li>\r\n<li>· Überführt die Schritte der angestrebten strategischen Entscheidungen und Prozesse vom Abstrakten ins Konkrete.</li>\r\n<li>· Vermittelt Mitarbeitenden und Stakeholdern die strategische Struktur und die Ziele.</li>\r\n<li>· Schafft einen erfolgreichen und nachhaltigen strategischen Entwicklungsprozess.</li>\r\n<li>· Macht Maßnahmen und Kennzahlen zum strategischen Ziel nachverfolgbar.</li>\r\n</ul>','<h4>Wertschöpfungsketten-<br>management</h4>\r\n<p>Es ist die Planung der Ressourcen im Einklang mit den Unternehmenszielen und das nutzbringende Management wertschöpfender Aktivitäten.</p>\r\n<p>Wertschöpfungskettenmanagement;</p>\r\n<ul>\r\n<li>· Bestimmt die Bedeutung der Kern- und Unterstützungsaktivitäten im Leistungsbereich des Unternehmens.</li>\r\n<li>· Sorgt dafür, dass Prozesse in der Reihenfolge ihrer Bedeutung und Maßnahmen voranschreiten.</li>\r\n<li>· Zeigt, auf welches Tätigkeitsfeld man sich konzentrieren sollte.</li>\r\n</ul>','<h4>Zukunftsorientierte <br> Planung</h4>\r\n<p>Im strategischen Managementsystem des Unternehmens ist dies die Planung der Zukunftsziele im Einklang mit Mission, Vision und Grundwerten.</p>\r\n<p>Zukunftsorientierte Planung;</p>\r\n<ul>\r\n<li>· Lässt das Unternehmen ganzheitlicher und strategischer in die Zukunft blicken.</li>\r\n<li>· Weist den Weg für die zu ergreifenden Maßnahmen.</li>\r\n<li>· Ermöglicht die Planung der Zukunftsziele im Unternehmen und die Verfolgung ihrer Umsetzung.</li>\r\n<li>· Macht strategische Erfolge nachhaltig.</li>\r\n</ul>','<p><br></p>','Strategische Planung','Strategy Mapping','Wertschöpfungskettenmanagement','Zukunftsorientierte Planung',NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('3','en','Risk Consultancy','RISK <br><span>CONSULTANCY</span>','<p><b>Risk is the effect of uncertainty on objectives. Risks of different scales exist in every area a business operates in. These risks can be managed with traditional methods or with next-generation risk management. Since traditional risk management methods only aim to prevent losses, businesses that want to make it easier to reach their goals and contribute to the value creation process are restructuring risk management holistically.</b></p>','<p>Next-generation risk management is a system that determines which risks/uncertainties need to be managed, and to what extent, in order to reach the defined goals and objectives, and that aims to ensure the management process proceeds as planned. Risk management is an integral component of decision-making in successful management.</p>\r\n<p>Risk Classes: Financial, Reputational, Operational, Strategic, Compliance and External Environment</p>','<p><b>Why Enterprise Risk Management?</b></p>','<p><u>Internal Factors</u></p>\r\n<p>• Possible changes in the system and processes</p>\r\n<p>• The need for fast and accurate decision-making</p>\r\n<p>• Organizational changes</p>\r\n<p>• Performance measurements</p>\r\n<p>• Relations with employees</p>\r\n<p>• Identification of risks</p>\r\n<p>• The need to respond to risks faster and more comprehensively than in the past</p>','<p><u>External Factors</u></p>\r\n<p>• Customer Expectations</p>\r\n<p>• Regulatory Changes</p>\r\n<p>• Economic Uncertainties</p>\r\n<p>• Technological Innovations</p>\r\n<p>• Increasing Competition</p>\r\n<p>• Globalization</p>','<p><u>Enterprise Risk Management;</u></p>\r\n<p>• Contributes to sustainable profitability and growth.</p>\r\n<p>• Minimizes income fluctuations.</p>\r\n<p>• Ensures decisions are taken with risk-based, sound methods.</p>\r\n<p>• Ensures preparedness for surprises.</p>\r\n<p>• Supports the realization of strategies.</p>\r\n<p>• Ensures opportunities and threats are identified comprehensively.</p>\r\n<p>• Increases competitiveness.</p>\r\n<p>• Ensures effective and efficient use of resources.</p>\r\n<p>• Supports compliance with laws and regulations.</p>\r\n<p>• Protects reputation and trust.</p>\r\n<p>• Supports the continuity of corporate governance quality.</p>\r\n<p><br>As Organik Consulting Services, in risk management we provide businesses with an <b>Enterprise Risk Management&nbsp;</b>service.</p>','<p>Tools: Business Analysis, Job Analysis, SWOT and PESTLE Analysis, Interviews, Focus Groups</p>\r\n<p>Deliverables:</p>\r\n<p>• Risk Maps</p>\r\n<p>• Control and Action Plans</p>\r\n<p>• Risk Monitoring and Evaluation System</p>\r\n<p>• Enterprise Risk Management Procedure</p>','<h4>Enterprise <br>Risk Management</h4>\r\n<p>It is the identification of potential events that may affect the business, their management in line with the business\'s risk appetite, and the provision of reasonable assurance for achieving objectives.</p>\r\n<p>Enterprise Risk Management;</p>\r\n<ul>\r\n<li>· Increases stakeholder value.</li>\r\n<li>· Ensures risks are managed in line with the business\'s risk appetite.</li>\r\n<li>· Creates a shared perception of risk across the business.</li>\r\n<li>· Ensures more effective and efficient use of resources.</li>\r\n<li>· Prevents surprises and minimizes losses.</li>\r\n<li>· Provides reasonable assurance regarding the achievement of objectives.</li>\r\n<li>· Focuses on opportunities and creates awareness of threats.</li>\r\n</ul>','<p><br></p>','<p><br></p>','<p><br></p>','<p><br></p>','Enterprise Risk Management',NULL,NULL,NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('3','de','Risikoberatung','RISIKO-<br><span>BERATUNG</span>','<p><b>Risiko ist die Auswirkung von Unsicherheit auf Ziele. In jedem Bereich, in dem Unternehmen tätig sind, bestehen Risiken unterschiedlichen Ausmaßes. Diese Risiken lassen sich mit traditionellen Methoden oder mit Risikomanagement der neuen Generation steuern. Da traditionelle Methoden nur Verluste verhindern sollen, strukturieren Unternehmen, die das Erreichen ihrer Ziele erleichtern und zum Wertschöpfungsprozess beitragen wollen, ihr Risikomanagement ganzheitlich neu.</b></p>','<p>Risikomanagement der neuen Generation ist ein System, das bestimmt, welche Risiken/Unsicherheiten in welchem Umfang gesteuert werden müssen, um die festgelegten Ziele zu erreichen, und das sicherstellen soll, dass der Managementprozess wie geplant abläuft. Risikomanagement ist ein untrennbarer Bestandteil der Entscheidungsfindung erfolgreicher Führung.</p>\r\n<p>Risikoklassen: Finanzen, Reputation, Betrieb, Strategie, Compliance und externes Umfeld</p>','<p><b>Warum unternehmensweites Risikomanagement?</b></p>','<p><u>Interne Faktoren</u></p>\r\n<p>• Mögliche Veränderungen in System und Prozessen</p>\r\n<p>• Bedarf an schneller und richtiger Entscheidungsfindung</p>\r\n<p>• Organisatorische Veränderungen</p>\r\n<p>• Leistungsmessungen</p>\r\n<p>• Beziehungen zu den Mitarbeitenden</p>\r\n<p>• Identifikation von Risiken</p>\r\n<p>• Bedarf, schneller und umfassender als früher auf Risiken zu reagieren</p>','<p><u>Externe Faktoren</u></p>\r\n<p>• Kundenerwartungen</p>\r\n<p>• Gesetzesänderungen</p>\r\n<p>• Wirtschaftliche Unsicherheiten</p>\r\n<p>• Technologische Innovationen</p>\r\n<p>• Zunehmender Wettbewerb</p>\r\n<p>• Globalisierung</p>','<p><u>Unternehmensweites Risikomanagement;</u></p>\r\n<p>• Trägt zu nachhaltiger Rentabilität und Wachstum bei.</p>\r\n<p>• Minimiert Ertragsschwankungen.</p>\r\n<p>• Sorgt für risikobasierte, fundierte Entscheidungen.</p>\r\n<p>• Stellt die Vorbereitung auf Überraschungen sicher.</p>\r\n<p>• Unterstützt die Umsetzung der Strategien.</p>\r\n<p>• Sorgt für die umfassende Ermittlung von Chancen und Risiken.</p>\r\n<p>• Steigert die Wettbewerbsfähigkeit.</p>\r\n<p>• Gewährleistet den wirksamen und effizienten Einsatz der Ressourcen.</p>\r\n<p>• Unterstützt die Einhaltung von Gesetzen und Vorschriften.</p>\r\n<p>• Schützt Reputation und Vertrauen.</p>\r\n<p>• Unterstützt die Kontinuität der Qualität der Unternehmensführung.</p>\r\n<p><br>Als Organik Beratungsdienstleistungen bieten wir Unternehmen im Risikomanagement die Leistung <b>Unternehmensweites Risikomanagement&nbsp;</b>an.</p>','<p>Instrumente: Unternehmensanalyse, Arbeitsanalyse, SWOT- und PESTLE-Analyse, Interviews, Fokusgruppen</p>\r\n<p>Ergebnisse:</p>\r\n<p>• Risikokarten</p>\r\n<p>• Kontroll- und Maßnahmenpläne</p>\r\n<p>• Risikoüberwachungs- und Bewertungssystem</p>\r\n<p>• Verfahren für unternehmensweites Risikomanagement</p>','<h4>Unternehmensweites <br>Risikomanagement</h4>\r\n<p>Es umfasst die Identifikation potenzieller Ereignisse, die das Unternehmen beeinflussen können, deren Steuerung entsprechend der Risikobereitschaft des Unternehmens und die Schaffung angemessener Sicherheit für das Erreichen der Ziele.</p>\r\n<p>Unternehmensweites Risikomanagement;</p>\r\n<ul>\r\n<li>· Steigert den Stakeholder-Wert.</li>\r\n<li>· Sorgt dafür, dass Risiken entsprechend der Risikobereitschaft des Unternehmens gesteuert werden.</li>\r\n<li>· Schafft ein gemeinsames Risikoverständnis im gesamten Unternehmen.</li>\r\n<li>· Gewährleistet den wirksameren und effizienteren Einsatz der Ressourcen.</li>\r\n<li>· Verhindert Überraschungen und minimiert Verluste.</li>\r\n<li>· Bietet angemessene Sicherheit hinsichtlich der Zielerreichung.</li>\r\n<li>· Konzentriert sich auf Chancen und schafft Bewusstsein für Risiken.</li>\r\n</ul>','<p><br></p>','<p><br></p>','<p><br></p>','<p><br></p>','Unternehmensweites Risikomanagement',NULL,NULL,NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('4','en','Total Quality Consultancy','TOTAL <br> QUALITY <br> <span>CONSULTANCY</span>','<p><b>According to the Turkish Standards Institution (TSE), quality is the sum of the characteristics of a product or service based on its ability to meet defined or potential needs. According to the Japanese Industrial Standards Committee (JIS), it is a production system that produces the product or service economically and responds to consumer demands.</b></p>','<p><b>While quality is generally understood as the quality of goods and services or product quality, product quality emerges as a result. This result is determined by numerous quality elements — above all service quality, system quality, process quality and management quality.</b></p>\r\n<p>In the information age, where development is rapid, competition grows by the day and the market keeps narrowing, businesses have to achieve lasting and sustainable growth in order to survive.</p>\r\n<p>In this context, businesses must absolutely not compromise on product and service quality in order to find a place for themselves in the competitive environment. On the other hand, for product and/or service quality to be continuous and to create competitive advantage, businesses need well-established and effectively managed quality elements.</p>','<p></p>','<p></p>','<p>Quality Management contributes to;</p>\r\n<p>• Reducing Costs</p>\r\n<p>• Increasing Competitiveness</p>\r\n<p>• Increasing Market Share</p>\r\n<p>• Increasing Customer Satisfaction</p>\r\n<p>• Increasing Profit</p>\r\n<p>• Increasing Employee Satisfaction.</p>','<p>As Organik Consulting Services, the services we offer within the quality elements are;</p>\r\n<p><span>Process Management</span></p>\r\n<p><span>Service Quality Management</span></p>\r\n<p><span>Integrated Management Systems</span></p>','<p>Tools: Business Analysis, Job Analysis, Work Studies, SWOT and PESTLE Analysis, Interviews, Focus Groups</p>','<h4>Process <br>Management</h4>\r\n<p>Process management aims to sustain, evaluate and analyze the work and effort for all the steps that turn inputs into outputs within businesses\' management, operational and support activities, and to increase their effectiveness through improvements.</p>\r\n<p>Process Management;</p>\r\n<ul>\r\n<li>· Increases the quality of getting work done by setting out the work to be done and the actors responsible for it.</li>\r\n<li>· Prevents work from being disrupted through the clear definition of responsibilities.</li>\r\n<li>· Contributes to decision-making by setting priorities.</li>\r\n<li>· Supports continuous development by creating opportunities for system improvement.</li>\r\n<li>· Ensures resources are used effectively and efficiently.</li>\r\n<li>· Eliminates negative factors such as errors, forgetting and neglect in the execution of activities.</li>\r\n<li>· Makes all activities transparent and measurable.</li>\r\n</ul>','<h4>Service Quality <br> Management</h4>\r\n<p>By measuring the quality level of the services businesses provide and the satisfaction levels of their customers, it enables action strategies to be created where improvement is needed and the system to be monitored holistically.</p>\r\n<p>Service Quality Management;</p>\r\n<ul>\r\n<li>· Ensures the service provided is measured and improved.</li>\r\n<li>· Increases service quality.</li>\r\n<li>· Enables the business side and the customer side to be evaluated on common ground.</li>\r\n<li>· Allows the service process and post-service controls to be run within a management model.</li>\r\n<li>· Contributes to the sustainability of the services the business delivers.</li>\r\n</ul>','<h4>Integrated Management <br> Systems</h4>\r\n<p>We provide consultancy services for businesses to obtain ISO 9001, ISO 14001 and ISO 45001 in particular, as well as the other certificates within the scope of the Integrated Management System.</p>\r\n<p>We work in cooperation with businesses throughout the entire process, from applying for the certificate to obtaining it.</p>\r\n<p>We also continue to support businesses in periodic certificate renewal and in adapting to changes made to the standards.</p>','<p><br></p>','<p><br></p>','Process Management','Service Quality Management','Integrated Management Systems',NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('4','de','Ganzheitliche Qualitätsberatung','GANZHEITLICHE <br> QUALITÄTS-<br> <span>BERATUNG</span>','<p><b>Nach dem türkischen Normungsinstitut (TSE) ist Qualität die Summe der Eigenschaften eines Produkts oder einer Dienstleistung, die auf der Fähigkeit beruhen, definierte oder mögliche Bedürfnisse zu erfüllen. Nach dem japanischen Normenkomitee (JIS) ist sie ein Produktionssystem, das das Produkt oder die Dienstleistung auf wirtschaftliche Weise herstellt und auf die Wünsche der Verbraucher eingeht.</b></p>','<p><b>Unter Qualität wird meist die Qualität von Waren und Dienstleistungen oder die Produktqualität verstanden — doch die Produktqualität ist ein Ergebnis. Dieses Ergebnis wird von zahlreichen Qualitätselementen bestimmt, allen voran Servicequalität, Systemqualität, Prozessqualität und Managementqualität.</b></p>\r\n<p>Im Informationszeitalter, in dem die Entwicklung rasant verläuft, der Wettbewerb täglich zunimmt und der Markt immer enger wird, müssen Unternehmen dauerhaftes und nachhaltiges Wachstum sichern, um zu überleben.</p>\r\n<p>In diesem Rahmen dürfen Unternehmen bei der Produkt- und Dienstleistungsqualität keinesfalls Abstriche machen, um sich im Wettbewerbsumfeld behaupten zu können. Damit die Produkt- und/oder Dienstleistungsqualität von Dauer ist und Wettbewerbsvorteile schafft, brauchen Unternehmen zudem gut etablierte und wirksam gesteuerte Qualitätselemente.</p>','<p></p>','<p></p>','<p>Qualitätsmanagement trägt bei zu;</p>\r\n<p>• Senkung der Kosten</p>\r\n<p>• Steigerung der Wettbewerbsfähigkeit</p>\r\n<p>• Erhöhung des Marktanteils</p>\r\n<p>• Steigerung der Kundenzufriedenheit</p>\r\n<p>• Steigerung des Gewinns</p>\r\n<p>• Steigerung der Mitarbeiterzufriedenheit.</p>','<p>Als Organik Beratungsdienstleistungen bieten wir innerhalb der Qualitätselemente folgende Leistungen an;</p>\r\n<p><span>Prozessmanagement</span></p>\r\n<p><span>Servicequalitätsmanagement</span></p>\r\n<p><span>Integrierte Managementsysteme</span></p>','<p>Instrumente: Unternehmensanalyse, Arbeitsanalyse, Arbeitsstudien, SWOT- und PESTLE-Analyse, Interviews, Fokusgruppen</p>','<h4>Prozess-<br>management</h4>\r\n<p>Das Prozessmanagement zielt darauf ab, für alle Schritte, die im Rahmen der Führungs-, Betriebs- und Unterstützungsaktivitäten der Unternehmen aus Eingaben Ergebnisse machen, die Arbeit und Anstrengungen aufrechtzuerhalten, zu bewerten und zu analysieren sowie ihre Wirksamkeit durch Verbesserungen zu steigern.</p>\r\n<p>Prozessmanagement;</p>\r\n<ul>\r\n<li>· Erhöht die Qualität der Arbeitsausführung, indem es die zu erledigenden Arbeiten und die Verantwortlichen benennt.</li>\r\n<li>· Verhindert Störungen im Arbeitsablauf durch klare Festlegung der Verantwortlichkeiten.</li>\r\n<li>· Trägt durch Priorisierung zum Entscheidungsprozess bei.</li>\r\n<li>· Fördert die kontinuierliche Entwicklung durch Verbesserungsmöglichkeiten in den Systemen.</li>\r\n<li>· Sorgt für den wirksamen und effizienten Einsatz der Ressourcen.</li>\r\n<li>· Beseitigt Fehler, Vergessen und Nachlässigkeit bei der Durchführung der Tätigkeiten.</li>\r\n<li>· Macht alle Tätigkeiten transparent und messbar.</li>\r\n</ul>','<h4>Servicequalitäts-<br>management</h4>\r\n<p>Durch Messung des Qualitätsniveaus der angebotenen Dienstleistungen und der Kundenzufriedenheit ermöglicht es die Entwicklung von Maßnahmenstrategien an verbesserungsbedürftigen Punkten und die ganzheitliche Überwachung des Systems.</p>\r\n<p>Servicequalitätsmanagement;</p>\r\n<ul>\r\n<li>· Sorgt für die Messung und Weiterentwicklung der erbrachten Dienstleistung.</li>\r\n<li>· Erhöht die Servicequalität.</li>\r\n<li>· Ermöglicht die Bewertung von Unternehmens- und Kundenseite auf gemeinsamer Grundlage.</li>\r\n<li>· Erlaubt es, den Serviceprozess und die Kontrollen nach der Leistungserbringung in einem Managementmodell zu führen.</li>\r\n<li>· Trägt zur Nachhaltigkeit der vom Unternehmen erbrachten Dienstleistungen bei.</li>\r\n</ul>','<h4>Integrierte Management-<br>systeme</h4>\r\n<p>Wir bieten Beratung, damit Unternehmen insbesondere ISO 9001, ISO 14001 und ISO 45001 sowie die weiteren Zertifikate im Rahmen des Integrierten Managementsystems erlangen können.</p>\r\n<p>Vom Antrag bis zum Erhalt des Zertifikats arbeiten wir während des gesamten Prozesses eng mit den Unternehmen zusammen.</p>\r\n<p>Darüber hinaus unterstützen wir Unternehmen bei der periodischen Zertifikatserneuerung und bei der Anpassung an Änderungen der Normen.</p>','<p><br></p>','<p><br></p>','Prozessmanagement','Servicequalitätsmanagement','Integrierte Managementsysteme',NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('5','en','Production Management Consultancy','PRODUCTION<br> MANAGEMENT <br><span>CONSULTANCY</span>','<p><b>Production is a critical function that directly affects a business\'s cost structure and its success in meeting customer demands.</b></p>','<p>Production Management is the development of the system that enables a business producing goods or services to produce in the most functional, economical and value-adding way.</p>','<p>Production Management;</p>','<p>• Reports whether goods and resources are used in the most effective way and provides improvement opportunities for possible situations.</p>\r\n<p>• Makes the product/service efficient.</p>\r\n<p>• Helps resources be used effectively and in a solution-oriented way.</p>\r\n<p>• Ensures the analyses and planning required to determine the production of goods/services in line with consumer demand.</p>','<p>• Determines how the machines and equipment in the business should be used, their maintenance and their costs.</p>\r\n<p>• Helps important stages such as quality and stock control run in a planned manner.</p>\r\n<p>• Ensures both orders and stocks are handled in a healthy order.</p>','<p>As Organik Consulting Services, the services we offer businesses in production management are;</p>\r\n<p><span>Asset Management</span></p>\r\n<p><span>Logistics Management</span></p>\r\n<p><span>Investment Management</span></p>\r\n<p><span>Procurement Management</span></p>','<p>Tools: Data Analysis, Job Analysis, SWOT and PESTLE Analysis, Interviews, Focus Groups</p>','<h4>Asset <br>Management</h4>\r\n<p>It is the ability to manage, with a systems approach, the processes of correctly acquiring, planning in coordination, maintaining, renewing and disposing of the assets the business owns, in order to maximize value in the production of goods or services and to meet stakeholder expectations.</p>\r\n<p>Asset Management;</p>\r\n<ul>\r\n<li>· Ensures processes are carried out in coordination.</li>\r\n<li>· Offers improved planning by enabling a proactive approach.</li>\r\n<li>· Reduces costs by optimizing resource use.</li>\r\n<li>· Enables the system to be monitored and tracked.</li>\r\n<li>· Creates a source of data and information for improving the system.</li>\r\n<li>· Provides consistent, prioritized and auditable risk management.</li>\r\n<li>· Ensures the effective use of the workforce.</li>\r\n</ul>','<h4>Logistics <br> Management</h4>\r\n<p>It is minimizing costs by increasing the effectiveness of all resources used, from transportation and distribution to the stocking of raw materials, semi-finished and finished products.</p>\r\n<p>Logistics Management;</p>\r\n<ul>\r\n<li>· Increases customer satisfaction.</li>\r\n<li>· Improves delivery performance.</li>\r\n<li>· Ensures continuity in production.</li>\r\n<li>· Helps reduce stocks.</li>\r\n<li>· Provides efficiency and, with it, an increase in capacity.</li>\r\n<li>· Lowers costs through the planning of management costs and enables savings.</li>\r\n<li>· Reduces logistics expenses.</li>\r\n<li>· Shortens the supply cycle time.</li>\r\n<li>· Builds resilience against sudden changes in the market.</li>\r\n</ul>','<h4>Investment <br> Management</h4>\r\n<p>It ensures that investment decisions committing resources to assets in order to generate income are taken in the most accurate way, considering benefits, costs and risks in line with changing market dynamics and business needs. Investment management covers the processes of creating and evaluating investment plans and implementing the investment so that business resources are used in the right areas.</p>\r\n<p>Investment Management;</p>\r\n<ul>\r\n<li>· Increases efficiency by directing business resources to the right areas.</li>\r\n<li>· Ensures investment decisions are prioritized.</li>\r\n<li>· Maximizes benefit by enabling the business to take the right investment decisions.</li>\r\n<li>· Allows the economic, technical and financial dimensions of the investment to be evaluated holistically.</li>\r\n<li>· Helps the business survive by keeping pace with technological, economic and cultural change.</li>\r\n</ul>','<h4>Procurement <br> Management</h4>\r\n<p>The main purpose of procurement management is to design the activities for acquiring the goods and services businesses need in a manageable way, together with all their components.</p>\r\n<p>Procurement Management;</p>\r\n<ul>\r\n<li>· Ensures the right product is obtained at the right time, in the right place, at the right price, in the right quantity and with the right method.</li>\r\n<li>· Ensures successful stock and order management.</li>\r\n<li>· Strengthens relationships with suppliers.</li>\r\n<li>· Sets out workflows by defining the procurement process.</li>\r\n<li>· Standardizes processes.</li>\r\n<li>· Clearly defines the activities that need to be carried out.</li>\r\n<li>· Sets out the roles and responsibilities required for activities to be carried out completely.</li>\r\n</ul>','<p><br></p>','Asset Management','Logistics Management','Investment Management','Procurement Management',NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('5','de','Beratung für Produktionsmanagement','PRODUKTIONS-<br>MANAGEMENT-<br><span>BERATUNG</span>','<p><b>Die Produktion ist eine kritische Funktion, die die Kostenstruktur eines Unternehmens und seinen Erfolg bei der Erfüllung der Kundenwünsche unmittelbar beeinflusst.</b></p>','<p>Produktionsmanagement ist die Entwicklung des Systems, das es einem Waren oder Dienstleistungen produzierenden Unternehmen ermöglicht, funktional, wirtschaftlich und mit höchstem Mehrwert zu produzieren.</p>','<p>Produktionsmanagement;</p>','<p>• Berichtet, ob Güter und Ressourcen bestmöglich eingesetzt werden, und eröffnet Verbesserungsmöglichkeiten für mögliche Situationen.</p>\r\n<p>• Macht das Produkt/die Dienstleistung effizient.</p>\r\n<p>• Hilft, Ressourcen wirksam und lösungsorientiert einzusetzen.</p>\r\n<p>• Sorgt für die erforderlichen Analysen und Planungen, um die Produktion von Waren/Dienstleistungen nach den Wünschen der Verbraucher auszurichten.</p>','<p>• Bestimmt, wie die vorhandenen Maschinen und Ausrüstungen richtig eingesetzt werden, sowie deren Wartung und Kosten.</p>\r\n<p>• Hilft, wichtige Phasen wie Qualitäts- und Bestandskontrolle planmäßig durchzuführen.</p>\r\n<p>• Sorgt dafür, dass sowohl Aufträge als auch Bestände in geordneter Weise abgewickelt werden.</p>','<p>Als Organik Beratungsdienstleistungen bieten wir Unternehmen im Produktionsmanagement folgende Leistungen an;</p>\r\n<p><span>Anlagenmanagement</span></p>\r\n<p><span>Logistikmanagement</span></p>\r\n<p><span>Investitionsmanagement</span></p>\r\n<p><span>Beschaffungsmanagement</span></p>','<p>Instrumente: Datenanalyse, Arbeitsanalyse, SWOT- und PESTLE-Analyse, Interviews, Fokusgruppen</p>','<h4>Anlagen-<br>management</h4>\r\n<p>Es ist die Fähigkeit, die Prozesse der richtigen Beschaffung, koordinierten Planung, Wartung, Erneuerung und Entsorgung der Vermögenswerte des Unternehmens mit einem Systemansatz zu steuern, um den Wert in der Produktion von Waren oder Dienstleistungen zu maximieren und die Erwartungen der Stakeholder zu erfüllen.</p>\r\n<p>Anlagenmanagement;</p>\r\n<ul>\r\n<li>· Sorgt für die koordinierte Fortführung der Prozesse.</li>\r\n<li>· Bietet verbesserte Planung durch einen proaktiven Ansatz.</li>\r\n<li>· Senkt die Kosten durch Optimierung des Ressourceneinsatzes.</li>\r\n<li>· Ermöglicht die Überwachung und Verfolgung des Systems.</li>\r\n<li>· Schafft eine Daten- und Informationsquelle zur Systemverbesserung.</li>\r\n<li>· Bietet konsistentes, priorisiertes und prüfbares Risikomanagement.</li>\r\n<li>· Gewährleistet den wirksamen Einsatz der Arbeitskräfte.</li>\r\n</ul>','<h4>Logistik-<br>management</h4>\r\n<p>Es bedeutet, die Kosten zu minimieren, indem die Wirksamkeit aller eingesetzten Ressourcen gesteigert wird — vom Transport und der Distribution bis zur Lagerung von Rohstoffen, Halbfertig- und Fertigprodukten.</p>\r\n<p>Logistikmanagement;</p>\r\n<ul>\r\n<li>· Steigert die Kundenzufriedenheit.</li>\r\n<li>· Verbessert die Lieferperformance.</li>\r\n<li>· Sichert die Kontinuität der Produktion.</li>\r\n<li>· Hilft bei der Reduzierung der Bestände.</li>\r\n<li>· Bringt Effizienz und damit Kapazitätssteigerung.</li>\r\n<li>· Senkt durch die Planung der Verwaltungskosten die Kosten und ermöglicht Einsparungen.</li>\r\n<li>· Reduziert die Logistikausgaben.</li>\r\n<li>· Verkürzt die Beschaffungszykluszeit.</li>\r\n<li>· Macht widerstandsfähig gegenüber plötzlichen Marktveränderungen.</li>\r\n</ul>','<h4>Investitions-<br>management</h4>\r\n<p>Es stellt sicher, dass Investitionsentscheidungen, mit denen Ressourcen zur Ertragserzielung in Vermögenswerte gebunden werden, unter Berücksichtigung von Nutzen, Kosten und Risiken im Einklang mit den sich wandelnden Marktdynamiken und Unternehmensbedürfnissen richtig getroffen werden. Das Investitionsmanagement umfasst die Erstellung und Bewertung von Investitionsplänen sowie die Umsetzung der Investition, damit die Unternehmensressourcen in den richtigen Bereichen eingesetzt werden.</p>\r\n<p>Investitionsmanagement;</p>\r\n<ul>\r\n<li>· Steigert die Effizienz, indem es Unternehmensressourcen in die richtigen Bereiche lenkt.</li>\r\n<li>· Sorgt für die Priorisierung der Investitionsentscheidungen.</li>\r\n<li>· Maximiert den Nutzen, indem es dem Unternehmen richtige Investitionsentscheidungen ermöglicht.</li>\r\n<li>· Erlaubt die ganzheitliche Bewertung der wirtschaftlichen, technischen und finanziellen Dimensionen der Investition.</li>\r\n<li>· Trägt zum Fortbestand des Unternehmens bei, indem es die Anpassung an technologische, wirtschaftliche und kulturelle Veränderungen ermöglicht.</li>\r\n</ul>','<h4>Beschaffungs-<br>management</h4>\r\n<p>Das Hauptziel des Beschaffungsmanagements ist es, die Tätigkeiten zur Beschaffung der von Unternehmen benötigten Waren und Dienstleistungen mit allen Komponenten steuerbar zu gestalten.</p>\r\n<p>Beschaffungsmanagement;</p>\r\n<ul>\r\n<li>· Sorgt dafür, dass das richtige Produkt zur richtigen Zeit, am richtigen Ort, zum richtigen Preis, in der richtigen Menge und mit der richtigen Methode beschafft wird.</li>\r\n<li>· Gewährleistet erfolgreiches Bestands- und Auftragsmanagement.</li>\r\n<li>· Stärkt die Beziehungen zu den Lieferanten.</li>\r\n<li>· Legt durch die Definition des Beschaffungsprozesses die Arbeitsabläufe fest.</li>\r\n<li>· Standardisiert die Prozesse.</li>\r\n<li>· Bestimmt klar die durchzuführenden Tätigkeiten.</li>\r\n<li>· Legt die Rollen und Verantwortlichkeiten fest, die für die vollständige Durchführung der Tätigkeiten erforderlich sind.</li>\r\n</ul>','<p><br></p>','Anlagenmanagement','Logistikmanagement','Investitionsmanagement','Beschaffungsmanagement',NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('6','en','Human Resources Consultancy','HUMAN <br> RESOURCES <br> <span>CONSULTANCY</span>','<p><b>Today, businesses have to compete in order to survive. In this environment of increasing competition, it has been recognized that to gain competitive advantage, businesses need to strengthen not only their new technologies and financial structures but also their human capital. Businesses have thus begun to invest in human resources and accelerated their work on people management.</b></p>','<p>The effective and efficient use of human resources influences all factors and stands out as a strategic element for businesses.</p>','<p>Areas of interest of Human Resources Management;</p>','<p>• Sourcing human resources</p>\r\n<p>• Using the resource effectively and efficiently</p>\r\n<p>• Providing training and development</p>\r\n<p>• Career planning</p>\r\n<p>• Performance appraisal</p>\r\n<p>• Compensation</p>\r\n<p>• Establishing the company culture</p>\r\n<p>• Increasing employee motivation</p>\r\n<p>Successful Human Resources Management;</p>\r\n<p>• Ensures the formation of human capital and the increase of organizational performance.</p>','<p>• Supports guiding and backing employees effectively, so that the business gains a competitive advantage aligned with its strategic goals and preserves that advantage.</p>\r\n<p>• Ways of working are developed and applied in line with strategic goals; the business adapts to changing conditions more quickly.</p>\r\n<p>• Raises employees\' satisfaction and quality of life along with business needs.</p>\r\n<p>As Organik Consulting Services, the services we offer businesses in the field of people management are;</p>','<p><span>Selection and Assessment System Design</span></p>\r\n<p><span>Strategic Workforce Planning</span></p>\r\n<p><span>Performance Management</span></p>\r\n<p><span>Career Management</span></p>\r\n<p><span>Talent Management</span></p>','<p>Tools: Business Analysis, Job Analysis, Work Studies, Surveys, SWOT and PESTLE Analysis, Interviews, Focus Groups, Employee Satisfaction Survey</p>\r\n<p><b>Deliverables:</b></p>\r\n<p>Selection and Assessment System Design</p>\r\n<p>Staffing Norms and Effective Workforce Plans</p>\r\n<p>Organization Handbook</p>\r\n<p>Career Planning System</p>\r\n<p>Talent Management System</p>\r\n<p>Performance Management System</p>\r\n<p>Human Resources Policy</p>\r\n<p>Human Resources Regulations</p>','<h4>Selection and Assessment<br>System Design</h4>\r\n<p>It is the design of the system required to place the right employee in the right job in order to close staffing gaps identified through HR planning or arising spontaneously during the period — finding people suited to roles with defined job descriptions, selecting them, placing them at the salary level the role requires and putting them through orientation.</p>\r\n<p>Selection and Assessment;</p>\r\n<ul>\r\n<li>· Ensures the right person is hired for the right job.</li>\r\n<li>· Supports high performance and work quality.</li>\r\n<li>· Ensures the effective use of human resources.</li>\r\n<li>· Increases employee job satisfaction and motivation.</li>\r\n<li>· Helps reduce the expenses incurred in getting work done.</li>\r\n<li>· Contributes to less physical and psychological effort being spent.</li>\r\n</ul>','<h4>Strategic <br> Workforce Planning</h4>\r\n<p>Treating employees — one of a business\'s most important resources — as a value, it covers the plans made as a result of analyses to direct the right person to the right job.</p>\r\n<p>By correctly defining functional divisions of labor, working roles, titles and positions — among the most important factors affecting efficiency in an organization — and by identifying training needs and setting performance standards, it ensures maximum benefit is obtained from the existing human resources.</p>\r\n<p>Strategic Workforce Planning;</p>\r\n<ul>\r\n<li>· Gives the business the opportunity to plan its workforce effectively.</li>\r\n<li>· Optimizes the business\'s efficiency and profitability.</li>\r\n<li>· Saves the business from unnecessary personnel costs and the employee from extra workload.</li>\r\n<li>· Enables businesses to determine their staffing needs.</li>\r\n<li>· Raises the quality of the work by defining the personnel qualifications required to do it.</li>\r\n<li>· Improves processes and reduces losses by preventing problems caused by assigning the wrong employee to the wrong job.</li>\r\n<li>· Forms a basis for the selection and hiring, evaluation, promotion and compensation of personnel.</li>\r\n</ul>','<h4>Performance <br> Management</h4>\r\n<p>It is the monitoring of performance by defining measurable performance criteria, in order to translate the company mission and vision into employee performance and to take the right managerial decisions. Performance management is handled within evaluation criteria formed by breaking goals, competencies, tasks and processes for the business and its units down to the individual.</p>\r\n<p>Performance Management;</p>\r\n<ul>\r\n<li>· Continuously tracks employee performance and delivers improvements in areas that need development.</li>\r\n<li>· Ensures employees\' individual participation in reaching goals and develops their motivation positively.</li>\r\n<li>· Supports continuous development by identifying employees\' training needs.</li>\r\n<li>· Contributes to successful career planning for employees.</li>\r\n<li>· Creates opportunity for the development of employees and the company.</li>\r\n</ul>','<h4>Career <br> Management</h4>\r\n<p>It supports employees in embracing the company culture and aligning with the organization\'s purpose, making them aware of the opportunities, options and outcomes within the business. Career management gives the employee a road map for defining career goals and reaching them.</p>\r\n<p>Career Management;</p>\r\n<ul>\r\n<li>· Helps employees steer their careers within the business successfully.</li>\r\n<li>· Increases internal motivation by taking into account employee expectations that are misunderstood or unspoken.</li>\r\n<li>· Increases belonging by reducing employees\' concerns about the future.</li>\r\n<li>· Clarifies the processes for meeting human resources needs.</li>\r\n<li>· Mobilizes employees whose productivity and motivation have fallen.</li>\r\n<li>· Manages employee expectations and prevents surprises that could cause disappointment.</li>\r\n<li>· Supports employee development and offers personal training opportunities.</li>\r\n<li>· Makes success and quality criteria sustainable.</li>\r\n</ul>','<h4>Talent <br>Management</h4>\r\n<p>It is the definition of the processes for determining the business\'s talent/competency needs, establishing the extent to which employees meet those needs, and training them to develop their talents accordingly. Along with current employees, prospective hires are also evaluated within this scope.</p>\r\n<p>Talent Management;</p>\r\n<ul>\r\n<li>· Ensures the talents/competencies the business needs are identified.</li>\r\n<li>· Reveals employees\' talents and enables their development.</li>\r\n<li>· Allows businesses to benefit from their employees\' talents in the best way.</li>\r\n<li>· Turns unnoticed talents into an opportunity for the business\'s success.</li>\r\n</ul>','Selection and Assessment System Design','Strategic Workforce Planning','Performance Management','Career Management','Talent Management','1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('6','de','Personalberatung','PERSONAL-<br><span>BERATUNG</span>','<p><b>Heutzutage müssen Unternehmen im Wettbewerb bestehen, um zu überleben. In diesem zunehmenden Wettbewerbsumfeld hat sich die Erkenntnis durchgesetzt, dass Unternehmen für Wettbewerbsvorteile neben neuen Technologien und einer starken Finanzstruktur auch ihr Humankapital stärken müssen. So haben Unternehmen begonnen, in ihre Personalressourcen zu investieren, und ihre Arbeit an der Personalführung beschleunigt.</b></p>','<p>Der wirksame und effiziente Einsatz der Personalressourcen wirkt sich auf alle Faktoren aus und erweist sich für Unternehmen als strategisches Element.</p>','<p>Handlungsfelder des Personalmanagements;</p>','<p>• Gewinnung von Personal</p>\r\n<p>• Wirksamer und effizienter Einsatz der Ressource</p>\r\n<p>• Schulung und Weiterentwicklung</p>\r\n<p>• Karriereplanung</p>\r\n<p>• Leistungsbeurteilung</p>\r\n<p>• Vergütung</p>\r\n<p>• Verankerung der Unternehmenskultur</p>\r\n<p>• Steigerung der Mitarbeitermotivation</p>\r\n<p>Erfolgreiches Personalmanagement;</p>\r\n<p>• Sorgt für den Aufbau von Humankapital und die Steigerung der Organisationsleistung.</p>','<p>• Unterstützt die wirksame Führung und Förderung der Mitarbeitenden, sodass das Unternehmen einen mit seinen strategischen Zielen im Einklang stehenden Wettbewerbsvorteil erlangt und bewahrt.</p>\r\n<p>• Arbeitsweisen werden im Einklang mit den strategischen Zielen entwickelt und angewendet; das Unternehmen passt sich schneller an veränderte Bedingungen an.</p>\r\n<p>• Steigert neben den Unternehmensbedürfnissen auch die Zufriedenheit und Lebensqualität der Mitarbeitenden.</p>\r\n<p>Als Organik Beratungsdienstleistungen bieten wir Unternehmen im Bereich Personalführung folgende Leistungen an;</p>','<p><span>Design von Auswahl- und Beurteilungssystemen</span></p>\r\n<p><span>Strategische Personalplanung</span></p>\r\n<p><span>Leistungsmanagement</span></p>\r\n<p><span>Karrieremanagement</span></p>\r\n<p><span>Talentmanagement</span></p>','<p>Instrumente: Unternehmensanalyse, Arbeitsanalyse, Arbeitsstudien, Umfragen, SWOT- und PESTLE-Analyse, Interviews, Fokusgruppen, Mitarbeiterzufriedenheitsstudie</p>\r\n<p><b>Ergebnisse:</b></p>\r\n<p>Design von Auswahl- und Beurteilungssystemen</p>\r\n<p>Personalbedarfsplanung und effektive Personaleinsatzpläne</p>\r\n<p>Organisationshandbuch</p>\r\n<p>Karriereplanungssystem</p>\r\n<p>Talentmanagementsystem</p>\r\n<p>Leistungsmanagementsystem</p>\r\n<p>Personalpolitik</p>\r\n<p>Personalrichtlinie</p>','<h4>Design von Auswahl- und<br>Beurteilungssystemen</h4>\r\n<p>Es ist das Design des Systems, das erforderlich ist, um durch die Personalplanung ermittelte oder im Laufe der Zeit von selbst entstehende Personallücken zu schließen, indem die richtige Person auf die richtige Stelle gesetzt wird — geeignete Personen für Stellen mit definierten Stellenbeschreibungen zu finden, auszuwählen, mit dem der Stelle entsprechenden Gehalt einzustellen und einzuarbeiten.</p>\r\n<p>Auswahl und Beurteilung;</p>\r\n<ul>\r\n<li>· Sorgt dafür, dass die richtige Person für die richtige Stelle eingestellt wird.</li>\r\n<li>· Unterstützt hohe Leistung und Arbeitsqualität.</li>\r\n<li>· Gewährleistet den wirksamen Einsatz der Personalressourcen.</li>\r\n<li>· Steigert Arbeitszufriedenheit und Motivation der Mitarbeitenden.</li>\r\n<li>· Hilft, die Ausgaben für die Arbeitsausführung zu senken.</li>\r\n<li>· Trägt dazu bei, dass weniger physischer und psychischer Aufwand nötig ist.</li>\r\n</ul>','<h4>Strategische <br> Personalplanung</h4>\r\n<p>Sie betrachtet die Mitarbeitenden — eine der wichtigsten Ressourcen der Unternehmen — als Wert und umfasst die auf Analysen beruhenden Pläne, um die richtige Person auf die richtige Stelle zu lenken.</p>\r\n<p>Durch die richtige Festlegung der funktionalen Arbeitsteilung, Arbeitsrollen, Titel und Positionen — zu den wichtigsten Effizienzfaktoren einer Organisation gehörend — sowie die Ermittlung des Schulungsbedarfs und die Festlegung von Leistungsstandards wird der maximale Nutzen aus den vorhandenen Personalressourcen gezogen.</p>\r\n<p>Strategische Personalplanung;</p>\r\n<ul>\r\n<li>· Bietet dem Unternehmen die Möglichkeit wirksamer Personalplanung.</li>\r\n<li>· Bringt Effizienz und Rentabilität des Unternehmens auf das optimale Niveau.</li>\r\n<li>· Bewahrt das Unternehmen vor unnötigen Personalkosten und die Mitarbeitenden vor zusätzlicher Arbeitslast.</li>\r\n<li>· Ermöglicht die Ermittlung des Personalbedarfs im Unternehmen.</li>\r\n<li>· Erhöht die Qualität der Arbeit durch Festlegung der erforderlichen Mitarbeiterqualifikationen.</li>\r\n<li>· Verbessert Prozesse und verringert Verluste, indem Probleme durch Fehlbesetzungen vermieden werden.</li>\r\n<li>· Bildet die Grundlage für Auswahl und Einstellung, Beurteilung, Beförderung und Vergütung des Personals.</li>\r\n</ul>','<h4>Leistungs-<br>management</h4>\r\n<p>Es ist die Überwachung der Leistung anhand messbarer Leistungskriterien, um Mission und Vision des Unternehmens in die Leistung der Mitarbeitenden zu übertragen und richtige Führungsentscheidungen treffen zu können. Das Leistungsmanagement stützt sich auf Bewertungskriterien, die entstehen, indem Ziele, Kompetenzen, Aufgaben und Prozesse des Unternehmens und seiner Einheiten bis auf die einzelne Person heruntergebrochen werden.</p>\r\n<p>Leistungsmanagement;</p>\r\n<ul>\r\n<li>· Verfolgt die Leistung der Mitarbeitenden kontinuierlich und sorgt für Verbesserungen in entwicklungsbedürftigen Bereichen.</li>\r\n<li>· Sichert die individuelle Beteiligung der Mitarbeitenden am Erreichen der Ziele und fördert ihre Motivation.</li>\r\n<li>· Unterstützt die kontinuierliche Entwicklung durch Ermittlung des Schulungsbedarfs.</li>\r\n<li>· Trägt zu erfolgreicher Karriereplanung der Mitarbeitenden bei.</li>\r\n<li>· Schafft Entwicklungsmöglichkeiten für Mitarbeitende und Unternehmen.</li>\r\n</ul>','<h4>Karriere-<br>management</h4>\r\n<p>Es unterstützt die Mitarbeitenden dabei, die Unternehmenskultur anzunehmen und sich mit dem Zweck der Organisation zu identifizieren, und macht sie auf die Chancen, Optionen und Ergebnisse im Unternehmen aufmerksam. Das Karrieremanagement bietet den Mitarbeitenden einen Fahrplan, um Karriereziele festzulegen und zu erreichen.</p>\r\n<p>Karrieremanagement;</p>\r\n<ul>\r\n<li>· Hilft den Mitarbeitenden, ihre Karriere im Unternehmen erfolgreich zu gestalten.</li>\r\n<li>· Steigert die interne Motivation, indem es unverstandene oder unausgesprochene Erwartungen berücksichtigt.</li>\r\n<li>· Erhöht die Zugehörigkeit, indem es Zukunftssorgen der Mitarbeitenden verringert.</li>\r\n<li>· Klärt die Prozesse zur Deckung des Personalbedarfs.</li>\r\n<li>· Aktiviert Mitarbeitende, deren Produktivität und Motivation gesunken sind.</li>\r\n<li>· Steuert die Erwartungen der Mitarbeitenden und verhindert Überraschungen, die zu Enttäuschungen führen könnten.</li>\r\n<li>· Fördert die Mitarbeiterentwicklung und bietet persönliche Weiterbildungsmöglichkeiten.</li>\r\n<li>· Macht Erfolg und Qualitätskriterien nachhaltig.</li>\r\n</ul>','<h4>Talent-<br>management</h4>\r\n<p>Es umfasst die Festlegung der Prozesse, mit denen der Talent-/Kompetenzbedarf des Unternehmens bestimmt, der Erfüllungsgrad dieser Anforderungen durch die Mitarbeitenden ermittelt und ihre entsprechende Weiterbildung gestaltet wird. Neben den aktuellen Mitarbeitenden werden auch künftige Neueinstellungen in diesem Rahmen bewertet.</p>\r\n<p>Talentmanagement;</p>\r\n<ul>\r\n<li>· Sorgt für die Ermittlung der vom Unternehmen benötigten Talente/Kompetenzen.</li>\r\n<li>· Macht die Talente der Mitarbeitenden sichtbar und ermöglicht ihre Entwicklung.</li>\r\n<li>· Erlaubt es Unternehmen, die Talente ihrer Mitarbeitenden bestmöglich zu nutzen.</li>\r\n<li>· Verwandelt unerkannte Talente in eine Chance für den Unternehmenserfolg.</li>\r\n</ul>','Design von Auswahl- und Beurteilungssystemen','Strategische Personalplanung','Leistungsmanagement','Karrieremanagement','Talentmanagement','1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('7','en','Public Services','PUBLIC <br> <span>SERVICES</span>','<p><b>Public services are continuous and regular activities offered to the public by the state or other public legal entities, or under their supervision and oversight, to meet and satisfy general and collective needs and to serve the public interest.</b></p>\r\n<p><b>The Development of Public Services;</b></p>','<p>New developments around the world and the rapid growth of population and migration toward city centers make it essential for local administrations to follow and implement the developments in this process.</p>\r\n<p>The urbanization process requires local administrations to deal with many different problems and to be open to new developments.</p>','<p>The fact that most of the problems concern human life and human demands, and that these demands consist of unlimited and difficult requests, makes the work of local governments even harder.</p>\r\n<p>In a management process whose solutions have become complex, institutions providing local services need to continuously develop and implement alternatives embodying a management approach that is more effective, efficient and responsive to the demands and wishes of their citizens.</p>','<p>In a management process whose solutions have become complex, institutions providing local services need to continuously develop and implement alternatives embodying a management approach that is more effective, efficient and responsive to the demands and wishes of their citizens.</p>\r\n<p>As Organik Consulting Services, within the scope of Public Services we carry out;</p>\r\n<p><span>System Design</span></p>\r\n<p><span>Guides and Handbooks</span></p>\r\n<p><span>Master Plan Preparation</span></p>','<p>activities.</p>','<p>Tools: System Analysis, Data Analysis, Focus Groups, Interviews, SWOT – PESTLE Analysis, Surveys and Research Studies, Field Observations, Citizen Satisfaction – Expectation Analyses, Literature Reviews, Legislation Analysis, Benchmarking Studies, Trend Analyses</p>','<p><b>Deliverables:</b></p>\r\n<p><b>Management Systems</b></p>\r\n<p>Public Square Management System</p>\r\n<p>Public Transport Management System</p>\r\n<p>Advertising Management System</p>\r\n<p>Lighting Management System</p>\r\n<p>Wholesale Market Management System</p>\r\n<p>Rural Development Management System</p>\r\n<p>Infrastructure Management System</p>\r\n<p>Construction Project Management System</p>\r\n<p>Construction Site Management System</p>\r\n<p>Tourism Management System</p>\r\n<p><b>Guides and Handbooks</b></p>\r\n<p>Urban Design Guide</p>\r\n<p>City Standards</p>\r\n<p>Kiosk Standards</p>\r\n<p>General Standards for Management Systems</p>\r\n<p><b>Master Plans</b></p>\r\n<p>Transportation Master Plan</p>\r\n<p>Logistics Master Plan</p>','<h4>System<br>Design</h4>\r\n<p>The main purpose of system design is to create the sustainable and manageable system needed for public activities — especially those carried out with many stakeholders — to keep pace with changing needs and expectations and to be run more effectively and without interruption.</p>\r\n<p>The system designs we carry out for public services;</p>\r\n<ul>\r\n<li>· Provide a holistic and sustainable management approach.</li>\r\n<li>· Ensure full and effective coordination among actors.</li>\r\n<li>· Enable values to be identified and increased.</li>\r\n<li>· Offer a monitorable and controllable system.</li>\r\n<li>· Make the system auditable.</li>\r\n<li>· Ensure the adoption of an approach compatible with the legal framework.</li>\r\n</ul>','<h4>Creating Guides<br> and Handbooks</h4>\r\n<p>The main purpose in creating guides and handbooks is to set out product, service and technical standards within the framework of the ideal system, together with assessments of the current processes in the functions defined in the literature for public elements.</p>\r\n<p>Guides and handbooks;</p>\r\n<ul>\r\n<li>· Give direction to the creation of livable urban spaces.</li>\r\n<li>· Increase the quality of urban life.</li>\r\n<li>· Define the relationships between actors.</li>\r\n<li>· Set out the areas of responsibility of the actors.</li>\r\n<li>· Establish the ideal system order.</li>\r\n</ul>','<h4>Master Plan<br> Preparation</h4>\r\n<p>Master plans are long-term, large-scale plans prepared for urban development and taken as the basis for implementation.</p>\r\n<p>The main purposes of master plans are;</p>\r\n<ul>\r\n<li>· To create a vision for the work to be carried out in the area they address.</li>\r\n<li>· To offer solutions to macro-level problems in the area they address.</li>\r\n<li>· To clarify and develop the roles and responsibilities of the organizations involved in development and transformation.</li>\r\n<li>· To support an area and ensure its development and renewal.</li>\r\n<li>· To develop proposals that will create public spaces with high-quality and sustainable services.</li>\r\n<li>To help coordinate different services in an area (such as education, tourism and transportation).</li>\r\n</ul>','<p><br></p>','<p><br></p>','System Design','Guides and Handbooks','Master Plan Preparation',NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('7','de','Öffentliche Dienstleistungen','ÖFFENTLICHE <br> <span>DIENSTLEISTUNGEN</span>','<p><b>Öffentliche Dienstleistungen sind kontinuierliche und regelmäßige Tätigkeiten, die vom Staat oder anderen öffentlich-rechtlichen Körperschaften bzw. unter deren Aufsicht und Kontrolle der Öffentlichkeit angeboten werden, um allgemeine und kollektive Bedürfnisse zu erfüllen und dem Gemeinwohl zu dienen.</b></p>\r\n<p><b>Die Entwicklung öffentlicher Dienstleistungen;</b></p>','<p>Neue Entwicklungen in der Welt und das rasche Bevölkerungs- und Migrationswachstum in Richtung der Stadtzentren machen es für Kommunalverwaltungen unumgänglich, die Entwicklungen in diesem Prozess zu verfolgen und umzusetzen.</p>\r\n<p>Der Urbanisierungsprozess verlangt von den Kommunalverwaltungen, sich mit vielen verschiedenen Problemen zu befassen und für neue Entwicklungen offen zu sein.</p>','<p>Dass die meisten Probleme das menschliche Leben und menschliche Wünsche betreffen und diese aus unbegrenzten und schwierigen Forderungen bestehen, erschwert die Arbeit der Kommunalverwaltungen zusätzlich.</p>\r\n<p>In einem Verwaltungsprozess mit komplex gewordenen Lösungen müssen Einrichtungen, die lokale Dienstleistungen erbringen, fortlaufend Alternativen entwickeln und umsetzen, die ein wirksameres, effizienteres und auf die Wünsche der Bürger eingehendes Verwaltungsverständnis verkörpern.</p>','<p>In einem Verwaltungsprozess mit komplex gewordenen Lösungen müssen Einrichtungen, die lokale Dienstleistungen erbringen, fortlaufend Alternativen entwickeln und umsetzen, die ein wirksameres, effizienteres und auf die Wünsche der Bürger eingehendes Verwaltungsverständnis verkörpern.</p>\r\n<p>Als Organik Beratungsdienstleistungen führen wir im Rahmen der öffentlichen Dienstleistungen folgende Tätigkeiten durch;</p>\r\n<p><span>Systemdesign</span></p>\r\n<p><span>Erstellung von Leitfäden und Handbüchern</span></p>\r\n<p><span>Masterplan-Erstellung</span></p>','<p></p>','<p>Instrumente: Systemanalyse, Datenanalyse, Fokusgruppen, Interviews, SWOT-/PESTLE-Analyse, Umfragen und Forschungsarbeiten, Feldbeobachtungen, Analysen zu Bürgerzufriedenheit und -erwartungen, Literaturrecherchen, Gesetzesanalyse, Benchmarking-Studien, Trendanalysen</p>','<p><b>Ergebnisse:</b></p>\r\n<p><b>Managementsysteme</b></p>\r\n<p>Platzmanagementsystem</p>\r\n<p>ÖPNV-Managementsystem</p>\r\n<p>Werbemanagementsystem</p>\r\n<p>Beleuchtungsmanagementsystem</p>\r\n<p>Großmarkt-Managementsystem</p>\r\n<p>Managementsystem für ländliche Entwicklung</p>\r\n<p>Infrastruktur-Managementsystem</p>\r\n<p>Bauprojekt-Managementsystem</p>\r\n<p>Baustellenmanagementsystem</p>\r\n<p>Tourismus-Managementsystem</p>\r\n<p><b>Leitfäden und Handbücher</b></p>\r\n<p>Leitfaden für Stadtgestaltung</p>\r\n<p>Stadtstandards</p>\r\n<p>Kioskstandards</p>\r\n<p>Allgemeine Standards für Managementsysteme</p>\r\n<p><b>Masterpläne</b></p>\r\n<p>Verkehrsmasterplan</p>\r\n<p>Logistikmasterplan</p>','<h4>System-<br>design</h4>\r\n<p>Das Hauptziel des Systemdesigns ist es, das nachhaltige und steuerbare System zu schaffen, das insbesondere für öffentliche Tätigkeiten mit vielen Beteiligten erforderlich ist, damit diese mit den sich wandelnden Bedürfnissen und Erwartungen Schritt halten und wirksamer sowie unterbrechungsfrei durchgeführt werden können.</p>\r\n<p>Unsere Systemdesigns für öffentliche Dienstleistungen;</p>\r\n<ul>\r\n<li>· Bieten ein ganzheitliches und nachhaltiges Verwaltungsverständnis.</li>\r\n<li>· Sorgen für vollständige und wirksame Koordination zwischen den Akteuren.</li>\r\n<li>· Ermöglichen die Ermittlung und Steigerung von Werten.</li>\r\n<li>· Bieten ein überwachbares und kontrollierbares System.</li>\r\n<li>· Machen das System prüfbar.</li>\r\n<li>· Sorgen für einen mit dem rechtlichen Rahmen vereinbaren Ansatz.</li>\r\n</ul>','<h4>Erstellung von Leitfäden<br> und Handbüchern</h4>\r\n<p>Das Hauptziel bei der Erstellung von Leitfäden und Handbüchern ist es, für öffentliche Elemente die in der Literatur definierten Funktionen mit den Erhebungen zu den Ist-Prozessen zusammenzuführen und im Rahmen des idealen Systems Produkt-, Dienstleistungs- und technische Standards festzulegen.</p>\r\n<p>Leitfäden und Handbücher;</p>\r\n<ul>\r\n<li>· Geben der Schaffung lebenswerter städtischer Räume die Richtung vor.</li>\r\n<li>· Steigern die Qualität des städtischen Lebens.</li>\r\n<li>· Bestimmen die Beziehungen zwischen den Akteuren.</li>\r\n<li>· Legen die Verantwortungsbereiche der Akteure fest.</li>\r\n<li>· Schaffen die ideale Systemordnung.</li>\r\n</ul>','<h4>Masterplan-<br>Erstellung</h4>\r\n<p>Masterpläne sind langfristige, groß angelegte Pläne, die für die Stadtentwicklung erstellt und als Grundlage der Umsetzung herangezogen werden.</p>\r\n<p>Die Hauptziele der Masterpläne sind;</p>\r\n<ul>\r\n<li>· Eine Vision für die Arbeiten in dem betreffenden Gebiet zu schaffen.</li>\r\n<li>· Lösungen für Probleme auf Makroebene in dem betreffenden Gebiet anzubieten.</li>\r\n<li>· Rollen und Verantwortlichkeiten der an Entwicklung und Wandel beteiligten Einrichtungen zu klären und weiterzuentwickeln.</li>\r\n<li>· Ein Gebiet zu fördern und seine Entwicklung und Erneuerung sicherzustellen.</li>\r\n<li>· Vorschläge zu entwickeln, die öffentliche Räume mit hochwertigen und nachhaltigen Dienstleistungen schaffen.</li>\r\n<li>Zur Koordination verschiedener Dienstleistungen in einem Gebiet (etwa Bildung, Tourismus, Verkehr) beizutragen.</li>\r\n</ul>','<p><br></p>','<p><br></p>','Systemdesign','Leitfäden und Handbücher','Masterplan-Erstellung',NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('8','en','Research Services','RESEARCH <br> <span>SERVICES</span>','<p>It covers the stages of collecting and analyzing, through various methods, the data businesses request on topics they want to research, understand or improve; identifying, in line with the results obtained, the aspects of the business open to improvement and development; and creating an action plan.</p>','<p>Businesses use research studies as a tool to gain foresight in order to increase their efficiency and performance.</p>','<p><br></p>','<p></p>','<p>Research studies offer businesses the opportunity to evaluate and analyze themselves impartially, and company efficiency increases when the action plans developed are followed. In this context, research is handled in two groups according to the type of method used (qualitative and quantitative).</p>','<p></p>','<p><br></p>','<h4>Quantitative <br>Research</h4>\r\n<p>Quantitative research enables numerical data to be measured, analyzed and evaluated. Within the scope of quantitative research conducted on businesses\' needs, demands and expectations, scientific methods are used to obtain, interpret and report the data.</p>\r\n<p>The research forms used while collecting data are designed specifically for each customer, in line with the business\'s needs and expectations. While our data collection methods take shape according to the research type and the request, the most common are Face-to-Face, Face-to-Face by Appointment, CATI (Computer-Assisted Telephone Interviewing), Online and Mailing methods. The collected data is analyzed with statistical methods.</p>\r\n<p>Our research processes are developed in line with customer needs and demands; we generally conduct perception, expectation, reputation, satisfaction and service quality research. Quantitative research makes the concepts of perception, expectation, reputation, satisfaction and service quality — which are of great importance to the business and vary across its stakeholders — measurable and trackable.</p>\r\n<p><b>Perception and Expectation Research;</b></p>\r\n<p>Customers\' expectations of the products and services offered by businesses, the degree to which those products and services meet customer expectations, and how they are perceived by customers are measured through perception and expectation research. This research offers businesses insight for developing products and services, increasing satisfaction and improving customer perception. It is important for the effectiveness of the research that businesses interpret the results correctly and take the necessary actions accordingly.</p>\r\n<p><b>Satisfaction Research;</b></p>\r\n<p>Satisfaction research measures the satisfaction of all of the business\'s stakeholders — above all employees, customers, dealers and suppliers — with the products and services offered. For businesses to survive, they must satisfy their stakeholders; high satisfaction brings competitiveness with it. Satisfaction research gives businesses the opportunity to identify their strengths and weaknesses against competitors, measure satisfaction levels at all touchpoints, detect problems and dissatisfaction where they exist, and develop solution proposals — creating room for continuous improvement.</p>\r\n<p><b>Reputation Research;</b></p>\r\n<p>Reputation is the perception and recognition of businesses\' strengths and weaknesses by stakeholders, customers and employees at every point of contact with the business. In the current competitive environment, reputation is more important than ever; protecting it and keeping it sustainable is becoming harder. Reputation research stands out as a way to generate foresight for the actions needed to develop reputation positively.</p>\r\n<p>Reputation research covers all the service areas businesses offer. The results, which reveal the business\'s perception through the eyes of its stakeholders, also allow businesses to compare themselves with their competitors.</p>\r\n<p><b>Service Quality Research;</b></p>\r\n<p>Today, when products and services increasingly resemble one another and price alone is not decisive, the most important way to make a difference is a high level of quality during and after the delivery of services at customer touchpoints. As quality service has become a priority for customers, businesses too must make quality a primary goal in the services they offer.</p>\r\n<p>Service quality research matters for total quality management because it enables businesses to measure, evaluate and report the service they provide with objective, numerical data and to prepare action plans. It is of great importance for delivering services accurately and reliably and for showing businesses the threats, opportunities, strengths and weaknesses in their service delivery. An increase in service quality simultaneously enables customer satisfaction to increase or to be maintained.</p>','<h4>Qualitative<br> Research</h4>\r\n<p>Qualitative research involves collecting, analyzing and interpreting data that cannot meaningfully be expressed in numbers. Its purpose is not to reach generalizations by putting results on a numerical basis, but to obtain in-depth knowledge of the topic that is the subject of the research. The knowledge obtained is analyzed in line with businesses\' needs and used for improvement.</p>\r\n<p><b>Workshops</b></p>\r\n<p>Workshops are a participatory meeting methodology aimed at reaching collective wisdom. They are a working format that makes it possible to find common ground, solve shared problems, determine what needs to be done to improve and develop, and choose common goals.</p>\r\n<p>The main purpose of workshops is to bring together all stakeholders affected by a given topic and gather their ideas, views and suggestions. Whereas in classic conference formats one or a few people present certain topics and the rest listen, in workshops the participants, in exactly the opposite format, talk and try to reach a conclusion.</p>\r\n<p>Our workshop organization starts with clarifying the topic and identifying the stakeholders, and is completed with registration and reception, moderation and reporting. Throughout the moderation, numerous group-work techniques are applied to obtain outputs fit for purpose. The data obtained through the techniques applied in the workshop is brought together, turned into meaningful information and reported.</p>\r\n<p><b>Focus Group Interviews</b></p>\r\n<p>Focus group interviews are one of the qualitative research methods in which people, selected especially from a particular sector, discuss a specific theme or view, and the interaction that emerges leads to data and results.</p>\r\n<p>The main purpose of the focus group interviews we conduct within our ongoing projects or on any independent topic is to develop solution proposals around a specific problem/situation, generate ideas, understand participants\' thoughts and learn about their attitudes.</p>\r\n<p>Focus group interviews are held with fewer participants than a workshop. Carrying out all the work required for planning the interviews, selecting the participants and conducting the moderation, and preparing post-interview reports that bring together the outputs fit for purpose, form the basic steps of this research method.</p>\r\n<p><b>In-Depth Interviews</b></p>\r\n<p>The most important difference between in-depth interviews and focus group meetings is that in-depth interviews are held one-on-one with participants about the research topic. This method makes it possible to learn participants\' more specific and more open expectations, attitudes and behaviors related to the core research problem.</p>\r\n<p>In-depth interviews offer the opportunity to approach the research problem more deeply. The interviewer asks the participant open-ended questions, ensuring the topic is examined in depth. The information obtained after the interview is reported and used to solve the problem.</p>\r\n<p><b>Benchmarking Studies</b></p>\r\n<p>In the global order, customer-oriented businesses that care about customer satisfaction have a mindset that adopts as a principle "doing the right thing when someone else makes a mistake". This understanding makes openness, careful listening and observation necessary in organizations, and encourages them.</p>\r\n<p>A benchmarking study is the process of creating a model in businesses\' future-oriented restructuring processes, and of determining and implementing development methods in line with that model.</p>\r\n<p>The aim of a benchmarking study is the development process of evaluating one\'s own products, services and practices together with competitors or other leading companies in the industry, in order to be "the best" in the chosen area.</p>\r\n<p>Benchmarking studies are carried out to achieve development by evaluating one\'s own products, services and practices together with competitors or other leading businesses in the sector, in order to be "the best" in the chosen area.</p>\r\n<p>In this context, our work is supported by literature reviews, good-practice research, observation forms and on-site visits, and reports are prepared containing the actions required for development.</p>','<p><br></p>','<p><br></p>','<p><br></p>','Quantitative Research','Qualitative Research',NULL,NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('8','de','Forschungsdienstleistungen','FORSCHUNGS-<br> <span>DIENSTLEISTUNGEN</span>','<p>Sie umfassen die Erhebung und Analyse der von Unternehmen angeforderten Daten mit verschiedenen Methoden zu Themen, die sie erforschen, verstehen oder verbessern möchten; die Ermittlung der verbesserungs- und entwicklungsfähigen Aspekte des Unternehmens anhand der Ergebnisse; und die Erstellung eines Maßnahmenplans.</p>','<p>Unternehmen nutzen Forschungsarbeiten als Instrument, um Voraussicht zu gewinnen und so ihre Effizienz und Leistung zu steigern.</p>','<p><br></p>','<p></p>','<p>Forschungsarbeiten bieten Unternehmen die Möglichkeit, sich unvoreingenommen zu bewerten und zu analysieren; wird den entwickelten Maßnahmenplänen gefolgt, steigt die Effizienz des Unternehmens. In diesem Rahmen wird die Forschung je nach Methodentyp (qualitativ und quantitativ) in zwei Gruppen behandelt.</p>','<p></p>','<p><br></p>','<h4>Quantitative <br>Forschung</h4>\r\n<p>Quantitative Forschung ermöglicht die Messung, Analyse und Bewertung numerischer Daten. Im Rahmen quantitativer Forschung zu Bedürfnissen, Anforderungen und Erwartungen der Unternehmen werden wissenschaftliche Methoden zur Gewinnung, Interpretation und Berichterstattung der Daten eingesetzt.</p>\r\n<p>Die bei der Datenerhebung verwendeten Fragebögen werden kundenspezifisch und passend zu den Bedürfnissen und Erwartungen des Unternehmens gestaltet. Unsere Erhebungsmethoden richten sich nach Forschungsart und Auftrag; verbreitet sind persönliche Interviews, terminierte persönliche Interviews, CATI (computergestützte Telefoninterviews), Online- und Mailing-Methoden. Die erhobenen Daten werden mit statistischen Verfahren analysiert.</p>\r\n<p>Unsere Forschungsprozesse werden entsprechend den Kundenbedürfnissen entwickelt; in der Regel führen wir Wahrnehmungs-, Erwartungs-, Reputations-, Zufriedenheits- und Servicequalitätsstudien durch. Quantitative Forschung macht die für das Unternehmen höchst bedeutsamen und je nach Stakeholder unterschiedlichen Konzepte Wahrnehmung, Erwartung, Reputation, Zufriedenheit und Servicequalität messbar und nachverfolgbar.</p>\r\n<p><b>Wahrnehmungs- und Erwartungsstudien;</b></p>\r\n<p>Mit Wahrnehmungs- und Erwartungsstudien werden die Erwartungen der Kunden an die von Unternehmen angebotenen Produkte und Dienstleistungen gemessen, ebenso wie der Grad, in dem diese den Kundenerwartungen entsprechen, und die Art, wie sie von den Kunden wahrgenommen werden. Diese Studien liefern Unternehmen Einblicke, um Produkte und Dienstleistungen weiterzuentwickeln, die Zufriedenheit zu steigern und die Kundenwahrnehmung positiv zu entwickeln. Für die Wirksamkeit der Forschung ist es wichtig, dass Unternehmen die Ergebnisse richtig interpretieren und entsprechende Maßnahmen ergreifen.</p>\r\n<p><b>Zufriedenheitsstudien;</b></p>\r\n<p>Zufriedenheitsstudien messen die Zufriedenheit aller Stakeholder des Unternehmens — vor allem Mitarbeitende, Kunden, Händler und Lieferanten — mit den angebotenen Produkten und Dienstleistungen. Um fortzubestehen, müssen Unternehmen ihre Stakeholder zufriedenstellen; hohe Zufriedenheit bringt Wettbewerbsfähigkeit mit sich. Zufriedenheitsstudien ermöglichen es Unternehmen, ihre Stärken und Schwächen gegenüber Wettbewerbern zu bestimmen, die Zufriedenheit an allen Kontaktpunkten zu messen, etwaige Probleme und Unzufriedenheit aufzudecken und Lösungsvorschläge zu entwickeln — und eröffnen so kontinuierliche Verbesserung.</p>\r\n<p><b>Reputationsstudien;</b></p>\r\n<p>Reputation ist die Wahrnehmung und Bekanntheit der Stärken und Schwächen von Unternehmen bei Stakeholdern, Kunden und Mitarbeitenden an allen Kontaktpunkten. Im aktuellen Wettbewerbsumfeld ist Reputation wichtiger denn je; sie zu schützen und nachhaltig zu erhalten wird schwieriger. Reputationsstudien sind wichtig, um Voraussicht für die Maßnahmen zu gewinnen, mit denen die Reputation positiv entwickelt werden kann.</p>\r\n<p>Reputationsstudien beziehen alle Leistungsbereiche der Unternehmen ein. Die Ergebnisse, die die Wahrnehmung des Unternehmens aus Sicht der Stakeholder zeigen, erlauben Unternehmen auch den Vergleich mit ihren Wettbewerbern.</p>\r\n<p><b>Servicequalitätsstudien;</b></p>\r\n<p>Heute, wo sich Produkte und Dienstleistungen zunehmend ähneln und der Preis allein nicht entscheidend ist, ist der wichtigste Weg, sich abzuheben, ein hohes Qualitätsniveau während und nach der Leistungserbringung an den Kundenkontaktpunkten. Da Servicequalität für Kunden zur Priorität geworden ist, müssen auch Unternehmen die Qualität ihrer Dienstleistungen vorrangig anstreben.</p>\r\n<p>Servicequalitätsstudien sind für das ganzheitliche Qualitätsmanagement wichtig, weil sie es Unternehmen ermöglichen, die erbrachte Leistung mit objektiven, numerischen Daten zu messen, zu bewerten, zu berichten und Maßnahmenpläne zu erstellen. Sie sind von großer Bedeutung für eine korrekte und zuverlässige Leistungserbringung und dafür, Unternehmen die Risiken, Chancen, Stärken und Schwächen ihrer Leistungserbringung aufzuzeigen. Steigende Servicequalität ermöglicht zugleich steigende oder dauerhaft gesicherte Kundenzufriedenheit.</p>','<h4>Qualitative<br> Forschung</h4>\r\n<p>Qualitative Forschung umfasst die Erhebung, Analyse und Interpretation von Daten, die sich nicht sinnvoll in Zahlen ausdrücken lassen. Ziel ist es nicht, Ergebnisse auf eine numerische Grundlage zu stellen und zu verallgemeinern, sondern vertiefte Erkenntnisse zum Forschungsthema zu gewinnen. Die gewonnenen Erkenntnisse werden entsprechend den Bedürfnissen der Unternehmen analysiert und für Verbesserungen genutzt.</p>\r\n<p><b>Workshops</b></p>\r\n<p>Workshops sind eine partizipative Sitzungsmethodik mit dem Ziel, zu gemeinsamer Erkenntnis zu gelangen. Sie sind ein Arbeitsformat, das es ermöglicht, gemeinsame Sichtweisen zu finden, gemeinsame Probleme zu lösen, zu bestimmen, was für Verbesserung und Entwicklung zu tun ist, und gemeinsame Ziele zu wählen.</p>\r\n<p>Hauptzweck von Workshops ist es, alle von einem Thema betroffenen Stakeholder zusammenzubringen und ihre Ideen, Ansichten und Vorschläge einzuholen. Während in klassischen Konferenzformaten eine oder wenige Personen bestimmte Themen vortragen und die übrigen zuhören, sprechen die Teilnehmenden in Workshops in genau umgekehrter Ordnung und versuchen, zu einem Ergebnis zu gelangen.</p>\r\n<p>Unsere Workshop-Organisation beginnt mit der Klärung des Themas und der Bestimmung der Stakeholder und wird mit Registrierung und Empfang, Moderation und Berichterstattung abgeschlossen. Während der Moderation werden zahlreiche Gruppenarbeitstechniken angewendet, um zweckdienliche Ergebnisse zu erzielen. Die dabei gewonnenen Daten werden zusammengeführt, in aussagekräftige Informationen übersetzt und berichtet.</p>\r\n<p><b>Fokusgruppengespräche</b></p>\r\n<p>Fokusgruppengespräche sind eine qualitative Forschungsmethode, bei der insbesondere aus einer bestimmten Branche ausgewählte Personen ein bestimmtes Thema oder eine Sichtweise diskutieren und die entstehende Interaktion zu Daten und Ergebnissen führt.</p>\r\n<p>Hauptzweck der Fokusgruppengespräche, die wir im Rahmen laufender Projekte oder zu einem unabhängigen Thema durchführen, ist es, zu einem bestimmten Problem/einer Situation Lösungsvorschläge zu entwickeln, Ideen zu generieren, die Gedanken der Teilnehmenden zu verstehen und ihre Einstellungen kennenzulernen.</p>\r\n<p>Fokusgruppengespräche finden mit weniger Teilnehmenden statt als ein Workshop. Die Planung der Gespräche, die Auswahl der Teilnehmenden und die Moderation sowie die anschließende Erstellung von Berichten mit den zweckdienlichen Ergebnissen bilden die Grundschritte dieser Methode.</p>\r\n<p><b>Tiefeninterviews</b></p>\r\n<p>Der wichtigste Unterschied zwischen Tiefeninterviews und Fokusgruppensitzungen besteht darin, dass beim Tiefeninterview mit den Teilnehmenden einzeln über das Forschungsthema gesprochen wird. Mit dieser Methode lassen sich die spezifischeren und offeneren Erwartungen, Einstellungen und Verhaltensweisen der Teilnehmenden zum zentralen Forschungsproblem erfassen.</p>\r\n<p>Tiefeninterviews ermöglichen eine tiefere Annäherung an das Forschungsproblem. Die interviewende Person stellt offene Fragen und sorgt so für eine eingehende Behandlung des Themas. Die gewonnenen Informationen werden berichtet und zur Problemlösung genutzt.</p>\r\n<p><b>Benchmarking-Studien</b></p>\r\n<p>In der globalen Ordnung haben kundenorientierte Unternehmen, denen Kundenzufriedenheit wichtig ist, eine Denkweise, die sich zum Prinzip macht, "das Richtige zu tun, wenn andere Fehler machen". Dieses Verständnis macht Offenheit, aufmerksames Zuhören und Beobachten in Organisationen notwendig und fördert sie.</p>\r\n<p>Eine Benchmarking-Studie ist der Vorgang, in zukunftsgerichteten Umstrukturierungsprozessen von Unternehmen ein Vorbildmodell zu schaffen und anhand dieses Modells Entwicklungsmethoden zu bestimmen und umzusetzen.</p>\r\n<p>Ziel einer Benchmarking-Studie ist der Entwicklungsprozess, die eigenen Produkte, Dienstleistungen und Praktiken gemeinsam mit Wettbewerbern oder anderen führenden Unternehmen der Branche zu bewerten, um im gewählten Bereich "der Beste" zu sein.</p>\r\n<p>Benchmarking-Studien werden durchgeführt, um im gewählten Bereich "der Beste" zu werden, indem eigene Produkte, Dienstleistungen und Praktiken gemeinsam mit Wettbewerbern oder anderen führenden Unternehmen des Sektors bewertet werden.</p>\r\n<p>In diesem Rahmen werden unsere Arbeiten durch Literaturrecherchen, Studien zu guten Praktiken, Beobachtungsbögen und Vor-Ort-Besuche unterstützt, und es werden Berichte mit den für die Entwicklung erforderlichen Maßnahmen erstellt.</p>','<p><br></p>','<p><br></p>','<p><br></p>','Quantitative Forschung','Qualitative Forschung',NULL,NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('9','en','Training Services','TRAINING <br> <span>SERVICES</span>','<p>In a society that changes and develops every day, businesses must constantly keep up with change and develop in order to achieve sustainable growth and success. As Organik Academy, we believe this process of change and development must be supported with training.</p>','<p>With our Organik Academy services, in the light of Education 5.0 and Society 5.0, we aim to create a sustainable, modern, innovative, growth-oriented and learning-centered ecosystem using the possibilities offered by ubiquitous technologies.</p>','<p><b>"Our Corporate Training Method: Bespoke"</b></p>','<p><br></p>','<p><b>Training Needs Map:</b> In line with our meetings and analyses, we determine together exactly what your business needs and which training it requires. We choose which tool and method to use for the training. In other words, we put your business through a training check-up.</p>','<p><b>Training and Trainer Matching:</b> Bringing together our expert trainers — active in academia and with professional knowledge and experience within the sector — we make the matches best suited to your sector and your needs.</p>','<p><b>Applicable Training Program:</b> We schedule the agreed training programs at times and locations we determine together with you.</p>','<h4>Our Training<br>Modules</h4>\r\n<p>From the hundreds of trainings under our training modules, you can choose those that suit your organization\'s needs and expectations. If you want to learn your organization\'s needs, contact us and benefit from our free corporate training check-up service.</p>\r\n<p><b>Corporate Development:</b> The trainings in the Corporate Development Module aim to equip company employees with corporate knowledge and give them the skills needed as elements of the business as a whole.</p>\r\n<p><b>Personal Development:</b> The trainings in the Personal Development Module aim to increase the employee\'s individual abilities and level of knowledge, ensuring efficiency and effectiveness in business activities.</p>\r\n<p><b>Professional and Technical Development:</b> The trainings in the Professional and Technical Development Module aim to train qualified people for professions.</p>\r\n<p><b>Strategy:</b> The trainings in the Strategy Module aim to instill a strategic approach so that businesses can achieve systematic and sustainable management.</p>\r\n<p><b>Management and Leadership:</b> The trainings in the Management and Leadership Module aim to convey managerial approaches and practices to the business\'s potential or current management staff and to develop managerial competencies.</p>\r\n<p><b>Transformation and Digitalization:</b> The trainings in the Transformation and Digitalization Module aim to create awareness about businesses\' transformation and change as they keep pace with the digital world and systems.</p>\r\n<p><b>Human Resources:</b> The trainings in the Human Resources Module aim to inform and build competency in all the activities carried out to bring personnel into the organization, place them and continuously increase their effectiveness.</p>\r\n<p><b>Marketing and Sales:</b> The trainings in the Marketing and Sales Module aim to instill today\'s sales and marketing strategies as well as the knowledge and skills for putting them into practice.</p>\r\n<p><b>Occupational Health and Safety:</b> The trainings in the Occupational Health and Safety Module aim to create a safety culture and awareness specific to each business, as well as to achieve noticeable results in reducing work accidents and occupational diseases.</p>\r\n<p><b>Finance and Accounting:</b> The trainings in the Finance and Accounting Module aim to give managers, employers or employees a financial perspective and to teach the effective management of existing assets and earnings.</p>\r\n<p><b>Digital Media:</b> The trainings in the Digital Media Module focus on the marketing trends and approaches reshaped by the influence of developing digital and social media platforms, and aim to share the foundations needed to establish effective digital media strategies.</p>\r\n<p><b>Commerce and E-Commerce:</b> The trainings in the Commerce and E-Commerce Module aim to strengthen the commerce and e-commerce infrastructure of the business or the employee and to build the knowledge and skills for putting them into practice.</p>\r\n<p><b>Project Management:</b> The trainings in the Project Management Module aim to convey project management tools and techniques in detail, providing in-depth knowledge within the framework of internationally accepted methodologies.</p>\r\n<p><b>Integrated Management Systems:</b> The trainings in the Integrated Management Systems Module aim to build knowledge and skills in management systems such as quality, environment, occupational health and safety, customer satisfaction and information security, as required by ISO Standards.</p>\r\n<p><b>Remote Working:</b> The trainings in the Remote Working Module aim to ensure effectiveness and efficiency in remote or office-independent working situations and to build the relevant practices.</p>','<h4>Our Training<br> Programs</h4>\r\n<p>Our training programs are built on the core competencies and level of knowledge a business or an employee should have. If you want to find out which training program you need, contact us and benefit from our free corporate check-up service.</p>\r\n<p><b>Management Development Program:</b> To reach organizational goals, businesses have different management levels with different powers, responsibilities and competencies. The Management Development Program has been prepared with the training and development needs of three separate levels in mind — Entry, Middle and Senior — for these differentiated management levels. In addition to the levels, the trainings were built around the 11 core qualities a manager should have, ensuring the integrity of the program.</p>\r\n<p>Entry-Level Manager: Entry-level managers are people who have just become managers or are about to be promoted into management. This level needs to acquire fundamental management skills and competency.</p>\r\n<p>Middle-Level Manager: Middle-level managers are of critical importance within the organization for implementing strategies, making decisions and managing change.</p>\r\n<p>Senior Manager: Senior managers are also called top executives. Top executives, who see the business as a whole, need their ability to initiate and sustain change strengthened, along with their strategic perspective.</p>\r\n<p><b>Strategy Program:</b> A strategic outlook enables competitiveness, future-focused thinking and the ability to act on goals. The Strategy Program was created around the analysis, planning, implementation and control stages of the strategic outlook. The program aims to make strategy part of the company culture and bring continuity to holistic management.</p>\r\n<p><b>Strategic Human Resources Development Program:</b> The strategic management of human resources and the development of personnel accordingly are of critical importance for businesses. The Strategic Human Resources Development Program was created around 10 areas of practice in human resources, such as job analysis, defining position competencies, recruitment and placement, compensation, performance, career and talent management. The program\'s aim is to equip the HR professional with the in-depth knowledge and skills to meet all their needs and expectations.</p>\r\n<p><b>Innovation and Transformation Program:</b> Preparing businesses\' systems and employees for the future in line with developing technology, global changes and innovations is extremely critical for their sustainability. The Innovation and Transformation Program aims to convey holistically to its participants the abilities to question, create, manage and sustain innovation.</p>\r\n<p><b>Remote Working Practices Program:</b> The trainings in the Remote Working Module aim to ensure effectiveness and efficiency in remote or office-independent working situations and to build the relevant practices.</p>\r\n<p><b>Corporate Development Program:</b> Corporate development has an important place in creating success in businesses. The Corporate Development Program sees systems and employees as a whole and focuses on corporate communication, belonging, effective resource management, total quality and performance. The program\'s aim is to present, as a whole, the fundamental and critical content that supports corporate development.</p>\r\n<p><b>Personal Development Program:</b> A business\'s success depends not only on its own corporate development but also on the individual and personal development of its employees. At this point, supporting employees\' continuous development and enabling them to discover their own potential is critically important. The Personal Development Program was created by holistically evaluating the person\'s needs and expectations and focusing on the core development areas the business requires. The program supports the development of the desired attitudes, behaviors and mindset in the person (the employee).</p>\r\n<p><b>Certificate Programs:</b> Certificate programs are delivered in partnership with universities.</p>\r\n<p><b>Workshop Practices and Gamification</b></p>\r\n<p>Workshop Practices and Gamification are extremely important for reinforcing trainings and making them stick. Workshops are, in fact, active training. Workshops held after training allow the knowledge gained to be used while still fresh, and contribute to developing the feelings of doing and completing work. This will help increase the performance of the business\'s employees, and feelings of happiness and being valued will prevail among them.</p>\r\n<p>Communication Workshop</p>\r\n<p>Marketing Workshop</p>\r\n<p>Brand Workshop</p>','<p><br></p>','<p><br></p>','<p><br></p>','Our Training Modules','Our Training Programs',NULL,NULL,NULL,'1');
INSERT IGNORE INTO `tablo_hizmetler_ceviri` (`KayitID`,`DilKodu`,`Baslik`,`Baslik2`,`Veri1`,`Veri2`,`Veri3`,`Veri4`,`Veri5`,`Veri6`,`Veri7`,`Veri8`,`Veri9`,`Veri10`,`Veri11`,`Veri12`,`BaslikTab1`,`BaslikTab2`,`BaslikTab3`,`BaslikTab4`,`BaslikTab5`,`YayinDurumu`) VALUES ('9','de','Schulungsdienstleistungen','SCHULUNGS-<br> <span>DIENSTLEISTUNGEN</span>','<p>In einer sich täglich wandelnden und entwickelnden Gesellschaft müssen Unternehmen für nachhaltiges Wachstum und Erfolg mit dem Wandel Schritt halten und sich weiterentwickeln. Als Organik Akademie sind wir überzeugt, dass dieser Wandel- und Entwicklungsprozess durch Schulungen unterstützt werden muss.</p>','<p>Mit den Leistungen der Organik Akademie wollen wir im Lichte von Bildung 5.0 und Gesellschaft 5.0 und mit den Möglichkeiten allgegenwärtiger Technologien ein nachhaltiges, modernes, innovatives, förderndes und lernzentriertes Ökosystem schaffen.</p>','<p><b>"Unsere Methode für Unternehmensschulungen: Bespoke"</b></p>','<p><br></p>','<p><b>Schulungsbedarfskarte:</b> Auf Grundlage unserer Gespräche und Analysen bestimmen wir gemeinsam, was genau Ihr Unternehmen braucht und welche Schulung erforderlich ist. Wir wählen aus, welches Instrument und welche Methode für die Schulung eingesetzt werden. Mit anderen Worten: Wir unterziehen Ihr Unternehmen einem Schulungs-Check-up.</p>','<p><b>Zuordnung von Schulung und Trainer:</b> Gemeinsam mit unserem Team aus fachkundigen Trainern — akademisch verankert und mit beruflichem Wissen und Erfahrung aus der Branche — nehmen wir die zu Ihrer Branche und Ihren Bedürfnissen passenden Zuordnungen vor.</p>','<p><b>Umsetzbares Schulungsprogramm:</b> Die festgelegten Schulungsprogramme planen wir zu gemeinsam bestimmten passenden Zeiten und an passenden Orten.</p>','<h4>Unsere Schulungs-<br>module</h4>\r\n<p>Aus den Hunderten von Schulungen unserer Module können Sie diejenigen auswählen, die den Bedürfnissen und Erwartungen Ihrer Organisation entsprechen. Wenn Sie den Bedarf Ihrer Organisation ermitteln möchten, kontaktieren Sie uns und nutzen Sie unseren kostenlosen Unternehmensschulungs-Check-up.</p>\r\n<p><b>Unternehmensentwicklung:</b> Die Schulungen im Modul Unternehmensentwicklung sollen die Mitarbeitenden mit unternehmensbezogenem Wissen ausstatten und ihnen die als Teil des Unternehmensganzen erforderlichen Fähigkeiten vermitteln.</p>\r\n<p><b>Persönliche Entwicklung:</b> Die Schulungen im Modul Persönliche Entwicklung sollen die individuellen Fähigkeiten und den Wissensstand der Mitarbeitenden erhöhen und so Effizienz und Wirksamkeit in den Unternehmenstätigkeiten sichern.</p>\r\n<p><b>Berufliche und technische Entwicklung:</b> Die Schulungen im Modul Berufliche und Technische Entwicklung zielen darauf ab, qualifizierte Fachkräfte für die Berufe auszubilden.</p>\r\n<p><b>Strategie:</b> Die Schulungen im Modul Strategie sollen den strategischen Ansatz vermitteln, damit Unternehmen eine systematische und nachhaltige Führung erreichen.</p>\r\n<p><b>Führung und Leadership:</b> Die Schulungen im Modul Führung und Leadership sollen den potenziellen oder aktuellen Führungskräften des Unternehmens Führungsansätze und -praktiken vermitteln und die Führungskompetenzen entwickeln.</p>\r\n<p><b>Transformation und Digitalisierung:</b> Die Schulungen im Modul Transformation und Digitalisierung wollen Bewusstsein für Wandel und Veränderung der Unternehmen bei der Anpassung an die digitale Welt und die Systeme schaffen.</p>\r\n<p><b>Personalwesen:</b> Die Schulungen im Modul Personalwesen sollen über alle Tätigkeiten zur Aufnahme, Platzierung und kontinuierlichen Wirksamkeitssteigerung des Personals informieren und entsprechende Kompetenzen aufbauen.</p>\r\n<p><b>Marketing und Vertrieb:</b> Die Schulungen im Modul Marketing und Vertrieb sollen neben der Vermittlung heutiger Vertriebs- und Marketingstrategien auch die Kenntnisse und Fähigkeiten für deren Anwendung aufbauen.</p>\r\n<p><b>Arbeitssicherheit und Gesundheitsschutz:</b> Die Schulungen im Modul Arbeitssicherheit und Gesundheitsschutz sollen neben einer unternehmensspezifischen Sicherheitskultur und einem entsprechenden Bewusstsein auch spürbare Ergebnisse bei der Verringerung von Arbeitsunfällen und Berufskrankheiten erzielen.</p>\r\n<p><b>Finanzen und Rechnungswesen:</b> Die Schulungen im Modul Finanzen und Rechnungswesen sollen Führungskräften, Arbeitgebern oder Mitarbeitenden eine finanzielle Perspektive vermitteln und den wirksamen Umgang mit vorhandenen Vermögenswerten und Erträgen lehren.</p>\r\n<p><b>Digitale Medien:</b> Die Schulungen im Modul Digitale Medien konzentrieren sich auf die durch digitale und soziale Medienplattformen neu geformten Marketingtrends und -ansätze und wollen die Grundlagen wirksamer Digitalstrategien vermitteln.</p>\r\n<p><b>Handel und E-Commerce:</b> Die Schulungen im Modul Handel und E-Commerce sollen die Handels- und E-Commerce-Infrastruktur des Unternehmens oder der Mitarbeitenden stärken und die Kenntnisse und Fähigkeiten für die Anwendung aufbauen.</p>\r\n<p><b>Projektmanagement:</b> Die Schulungen im Modul Projektmanagement sollen im Rahmen international anerkannter Methodiken vertieftes Wissen vermitteln und Werkzeuge und Techniken des Projektmanagements im Detail weitergeben.</p>\r\n<p><b>Integrierte Managementsysteme:</b> Die Schulungen im Modul Integrierte Managementsysteme sollen Kenntnisse und Fähigkeiten zu Managementsystemen wie Qualität, Umwelt, Arbeitssicherheit, Kundenzufriedenheit und Informationssicherheit gemäß den ISO-Normen aufbauen.</p>\r\n<p><b>Remote-Arbeit:</b> Die Schulungen im Modul Remote-Arbeit sollen Wirksamkeit und Effizienz bei Remote- oder bürounabhängiger Arbeit sichern und die entsprechenden Praktiken vermitteln.</p>','<h4>Unsere Schulungs-<br>programme</h4>\r\n<p>Unsere Schulungsprogramme beruhen auf den Kernkompetenzen und dem Wissensstand, über die ein Unternehmen oder eine Mitarbeiterin bzw. ein Mitarbeiter verfügen sollte. Wenn Sie erfahren möchten, welches Schulungsprogramm Sie benötigen, kontaktieren Sie uns und nutzen Sie unseren kostenlosen Unternehmens-Check-up.</p>\r\n<p><b>Führungskräfte-Entwicklungsprogramm:</b> Um Organisationsziele zu erreichen, gibt es in Unternehmen verschiedene Führungsebenen mit unterschiedlichen Befugnissen, Verantwortlichkeiten und Kompetenzen. Das Programm wurde für die Schulungs- und Entwicklungsbedürfnisse dreier Ebenen erstellt: Einstiegs-, mittlere und obere Ebene. Zusätzlich wurden die Schulungen um die 11 Kerneigenschaften herum aufgebaut, die eine Führungskraft besitzen sollte, sodass das Programm ganzheitlich bleibt.</p>\r\n<p>Führungskraft der Einstiegsebene: Personen, die gerade Führungskraft geworden sind oder befördert werden sollen. Auf dieser Ebene müssen grundlegende Führungsfähigkeiten und -kompetenz erworben werden.</p>\r\n<p>Führungskraft der mittleren Ebene: Sie ist für die Umsetzung der Strategien, das Treffen von Entscheidungen und das Management des Wandels in der Organisation von kritischer Bedeutung.</p>\r\n<p>Obere Führungskraft: Auch Topmanager genannt. Bei den oberen Führungskräften, die das Unternehmen als Ganzes sehen, müssen die Fähigkeit, Wandel anzustoßen und fortzuführen, sowie der strategische Blick gestärkt werden.</p>\r\n<p><b>Strategieprogramm:</b> Der strategische Blick ermöglicht Wettbewerbsfähigkeit, zukunftsorientiertes Denken und zielgerichtetes Handeln. Das Strategieprogramm wurde für die Phasen Analyse, Planung, Umsetzung und Kontrolle des strategischen Blicks erstellt. Es will Strategie zur Unternehmenskultur machen und der ganzheitlichen Führung Kontinuität verleihen.</p>\r\n<p><b>Programm für strategische Personalentwicklung:</b> Das strategische Management der Personalressourcen und die entsprechende Entwicklung des Personals sind für Unternehmen von kritischer Bedeutung. Das Programm wurde unter Berücksichtigung von 10 Anwendungsfeldern des Personalwesens erstellt — etwa Arbeitsanalyse, Definition von Positionskompetenzen, Einstellung und Platzierung, Vergütung, Leistungs-, Karriere- und Talentmanagement. Ziel ist es, HR-Fachleuten das vertiefte Wissen und Können zu vermitteln, das alle ihre Bedürfnisse und Erwartungen abdeckt.</p>\r\n<p><b>Innovations- und Transformationsprogramm:</b> Die Vorbereitung der Systeme und Mitarbeitenden auf die Zukunft im Einklang mit Technologie, globalen Veränderungen und Innovationen ist für die Nachhaltigkeit der Unternehmen äußerst kritisch. Das Programm will den Teilnehmenden die Fähigkeiten, Innovation zu hinterfragen, zu schaffen, zu steuern und fortzuführen, ganzheitlich vermitteln.</p>\r\n<p><b>Programm für Remote-Arbeitspraktiken:</b> Die Schulungen im Modul Remote-Arbeit sollen Wirksamkeit und Effizienz bei Remote- oder bürounabhängiger Arbeit sichern und die entsprechenden Praktiken vermitteln.</p>\r\n<p><b>Programm Unternehmensentwicklung:</b> Die Unternehmensentwicklung hat einen wichtigen Platz beim Entstehen von Erfolg. Das Programm sieht Systeme und Mitarbeitende als Ganzes und konzentriert sich auf Unternehmenskommunikation, Zugehörigkeit, wirksames Ressourcenmanagement, ganzheitliche Qualität und Leistung. Ziel ist es, die grundlegenden und kritischen Inhalte, die die Unternehmensentwicklung fördern, als Ganzes zu vermitteln.</p>\r\n<p><b>Programm Persönliche Entwicklung:</b> Der Erfolg eines Unternehmens hängt neben der eigenen Entwicklung auch von der individuellen und persönlichen Entwicklung der Mitarbeitenden ab. Deshalb ist es entscheidend, ihre kontinuierliche Entwicklung zu fördern und ihnen zu ermöglichen, ihr Potenzial zu entdecken. Das Programm wurde durch ganzheitliche Bewertung der Bedürfnisse und Erwartungen der Person und mit Fokus auf die für das Unternehmen wesentlichen Entwicklungsfelder erstellt. Es unterstützt die Entwicklung der gewünschten Haltung, des Verhaltens und der Denkweise bei der Person (den Mitarbeitenden).</p>\r\n<p><b>Zertifikatsprogramme:</b> Zertifikatsprogramme werden in Kooperation mit Universitäten angeboten.</p>\r\n<p><b>Workshop-Anwendungen und Gamification</b></p>\r\n<p>Für die Festigung und Nachhaltigkeit der Schulungen sind Workshop-Arbeiten und Gamification äußerst wichtig. Workshops sind im Grunde aktives Training. Nach der Schulung durchgeführte Workshops ermöglichen es, das erworbene Wissen anzuwenden, solange es frisch ist, und fördern das Gefühl, Arbeit zu leisten und abzuschließen. So steigt die Leistung der Mitarbeitenden, und Zufriedenheit und das Gefühl der Wertschätzung überwiegen.</p>\r\n<p>Kommunikationsworkshop</p>\r\n<p>Marketingworkshop</p>\r\n<p>Markenworkshop</p>','<p><br></p>','<p><br></p>','<p><br></p>','Unsere Schulungsmodule','Unsere Schulungsprogramme',NULL,NULL,NULL,'1');
INSERT IGNORE INTO `tablo_metinler_ceviri` (`KayitID`,`DilKodu`,`Metin0`,`Metin1`,`Metin2`,`Metin3`,`Metin4`,`Metin5`,`Metin6`,`Metin7`,`Metin8`,`Metin9`,`Metin10`,`Metin11`,`Metin12`,`Metin13`,`Metin14`,`Metin15`,`YayinDurumu`) VALUES ('2','en','<p>Organik Consulting Services has been providing consultancy in corporate development, strategy, human resources, training, total quality and public services for more than 20 years. It continues to operate in various fields of the manufacturing and service sectors, primarily in energy and transportation.</p>','https://www.youtube.com/watch?v=dRoZOhYbO5c','<p>Organik Consulting Services has been providing consultancy in corporate development, strategy, human resources, training, total quality and public services for more than 20 years. It continues to operate in various fields of the manufacturing and service sectors, primarily in energy and transportation.</p>\r\n<p>With its expert team at the Istanbul head office and the Ankara office, together with its management and academic advisors, Organik Consulting Services has delivered a large number of projects. In projects carried out with customer needs and expectations as well as sector trends in mind, it has adopted the 4T methodology (Tanıma-Discover, Teşhis-Diagnose, Tedavi-Treat, Takip-Track).</p>','<ul>\r\n<li>Customer Focus</li>\r\n<li>Employee Happiness</li>\r\n<li>Sustainable Environment</li>\r\n<li>Continuous Improvement Focused on Service Quality</li>\r\n<li>Innovative and Original Approach</li>\r\n</ul>','<h3>Our Mission</h3>\r\n<p>To produce high value-added solutions that support the corporate development of businesses and organizations in order to increase their competitiveness, covering their unrevealed needs as well.</p>\r\n<h3>Our Vision</h3>\r\n<p>To become a recognized brand in the consulting sector and an international company through value-creating solutions outside the lines.</p>\r\n<h3>Our Integrated Policy</h3>\r\n<p>Through its Integrated Management System, our company pursues a policy that covers all of its activities in line with its vision and mission while complying with Integrated Management System standards. To this end;</p>\r\n<ul>\r\n<li>With the full participation of our employees, we internalize all processes from service inception to delivery within a life-cycle approach — in research, in fulfilling compliance obligations, in risk and opportunity assessments, and in training.</li>\r\n<li>We aim for a total quality approach that complies with all applicable laws, standards and regulations and attaches importance to continuous improvement and development.</li>\r\n<li>Identifying the waste arising from our activities, keeping it under control, contributing to recycling and neutralizing what cannot be recycled are among our core principles.</li>\r\n<li>We ensure preparedness for potential emergencies, establish and implement control systems that identify near-miss incidents and prevent their occurrence, keep possible damages/impacts at the lowest level should an emergency occur, and define effective communication channels.</li>\r\n<li>We approach all interested parties with transparency and work customer-focused by deeply understanding their requests, suggestions, complaints and expectations.</li>\r\n</ul>','<p>For more than twenty years, together with our business partners, <br>we have been carrying out projects and events with broad participation <br>and conducting studies that shape the sector.</p>','<h4>"Focus on being productive instead of busy."<br>Tim Ferriss</h4>','<p>Coming together is a beginning, <br>\r\nkeeping together is progress, <br>\r\nworking together is success.<br>Henry Ford</p>','<h6>We are aware that success is only possible with competent employees and effective teamwork. We continue our activities with value-adding projects delivered by our expert and experienced team.</h6>','<p>Alongside the high value-added solutions we offer to organizations,<br>we address current topics in business management<br>from a different perspective, drawing on our sector experience.<br></p>','<h4>"Those who insist on using yesterday\'s methods in today\'s world <br>\r\nwill not be in business tomorrow."<br>John C. Maxwell</h4>','<p>The privacy / personal data protection (KVKK) text will be placed here...</p>',NULL,NULL,NULL,NULL,'1');
INSERT IGNORE INTO `tablo_metinler_ceviri` (`KayitID`,`DilKodu`,`Metin0`,`Metin1`,`Metin2`,`Metin3`,`Metin4`,`Metin5`,`Metin6`,`Metin7`,`Metin8`,`Metin9`,`Metin10`,`Metin11`,`Metin12`,`Metin13`,`Metin14`,`Metin15`,`YayinDurumu`) VALUES ('2','de','<p>Organik Beratungsdienstleistungen bietet seit mehr als 20 Jahren Beratung in den Bereichen Unternehmensentwicklung, Strategie, Personalwesen, Weiterbildung, ganzheitliches Qualitätsmanagement und öffentliche Dienstleistungen an. Das Unternehmen ist in verschiedenen Feldern des Produktions- und Dienstleistungssektors tätig, vor allem in der Energie- und Verkehrsbranche.</p>','https://www.youtube.com/watch?v=dRoZOhYbO5c','<p>Organik Beratungsdienstleistungen bietet seit mehr als 20 Jahren Beratung in den Bereichen Unternehmensentwicklung, Strategie, Personalwesen, Weiterbildung, ganzheitliches Qualitätsmanagement und öffentliche Dienstleistungen an. Das Unternehmen ist in verschiedenen Feldern des Produktions- und Dienstleistungssektors tätig, vor allem in der Energie- und Verkehrsbranche.</p>\r\n<p>Mit seinem Expertenteam am Hauptsitz Istanbul und im Büro Ankara sowie seinen Management- und akademischen Beratern hat Organik Beratungsdienstleistungen zahlreiche Projekte realisiert. Bei Projekten, die unter Berücksichtigung der Bedürfnisse und Erwartungen der Kunden sowie der Branchentrends durchgeführt werden, kommt die 4T-Methodik (Erkennen, Diagnostizieren, Behandeln, Nachverfolgen) zum Einsatz.</p>','<ul>\r\n<li>Kundenorientierung</li>\r\n<li>Mitarbeiterzufriedenheit</li>\r\n<li>Nachhaltige Umwelt</li>\r\n<li>Kontinuierliche Verbesserung mit Fokus auf Servicequalität</li>\r\n<li>Innovativer und origineller Ansatz</li>\r\n</ul>','<h3>Unsere Mission</h3>\r\n<p>Lösungen mit hohem Mehrwert zu entwickeln, die die Unternehmensentwicklung von Betrieben und Organisationen unterstützen, ihre Wettbewerbsfähigkeit steigern und auch ihre noch nicht erkannten Bedürfnisse abdecken.</p>\r\n<h3>Unsere Vision</h3>\r\n<p>Mit wertschaffenden Lösungen jenseits der Norm eine anerkannte Marke in der Beratungsbranche und ein internationales Unternehmen zu werden.</p>\r\n<h3>Unsere integrierte Politik</h3>\r\n<p>Unser Unternehmen verfolgt mit seinem Integrierten Managementsystem eine Politik, die im Einklang mit Vision und Mission alle Tätigkeiten umfasst und zugleich den Standards des Integrierten Managementsystems entspricht. Zu diesem Zweck gilt:</p>\r\n<ul>\r\n<li>Unter voller Beteiligung unserer Mitarbeitenden verinnerlichen wir alle Prozesse vom Beginn der Dienstleistung bis zur Erbringung im Rahmen eines Lebenszyklus-Ansatzes — in der Forschung, bei der Erfüllung von Compliance-Pflichten, bei Risiko- und Chancenbewertungen sowie in Schulungen.</li>\r\n<li>Wir streben einen ganzheitlichen Qualitätsansatz an, der alle geltenden Gesetze, Normen und Vorschriften einhält und kontinuierlicher Verbesserung und Entwicklung hohen Stellenwert beimisst.</li>\r\n<li>Die Ermittlung und Kontrolle der aus unseren Tätigkeiten entstehenden Abfälle, der Beitrag zum Recyclingprozess und die Unschädlichmachung nicht recycelbarer Abfälle gehören zu unseren Grundprinzipien.</li>\r\n<li>Wir stellen die Vorbereitung auf mögliche Notfälle sicher, errichten und betreiben Kontrollsysteme, die Beinahe-Ereignisse identifizieren und deren Eintreten verhindern, halten mögliche Schäden/Auswirkungen im Notfall so gering wie möglich und definieren wirksame Kommunikationswege.</li>\r\n<li>Wir begegnen allen interessierten Parteien mit Transparenz und arbeiten kundenorientiert, indem wir ihre Wünsche, Vorschläge, Beschwerden und Erwartungen eingehend verstehen.</li>\r\n</ul>','<p>Seit über zwanzig Jahren führen wir gemeinsam mit unseren Geschäftspartnern <br>Projekte und Veranstaltungen mit breiter Beteiligung durch <br>und leisten richtungsweisende Arbeit für die Branche.</p>','<h4>"Konzentrieren Sie sich darauf, produktiv statt beschäftigt zu sein."<br>Tim Ferriss</h4>','<p>Zusammenkommen ist ein Beginn, <br>\r\nZusammenbleiben ist ein Fortschritt, <br>\r\nZusammenarbeiten ist Erfolg.<br>Henry Ford</p>','<h6>Wir sind uns bewusst, dass Erfolg nur mit kompetenten Mitarbeitenden und wirksamer Teamarbeit möglich ist. Mit unserem fachkundigen, erfahrenen Team und wertschöpfenden Projekten setzen wir unsere Tätigkeit fort.</h6>','<p>Neben den Lösungen mit hohem Mehrwert, die wir Organisationen anbieten,<br>behandeln wir aktuelle Themen der Unternehmensführung<br>mit unserer Branchenerfahrung aus einem anderen Blickwinkel.<br></p>','<h4>"Wer darauf besteht, die Methoden von gestern in der Welt von heute anzuwenden, <br>\r\nwird im Geschäft von morgen nicht mehr dabei sein."<br>John C. Maxwell</h4>','<p>Der Text zum Datenschutz / Schutz personenbezogener Daten (KVKK) wird hier eingefügt...</p>',NULL,NULL,NULL,NULL,'1');
