INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1450','de','swot-analyse-eltemtek','SWOT-Analyse / ELTEMTEK','Wir haben die SWOT-Analyse mit ELTEMTEK abgeschlossen.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1449','en','organik-named-the-30th-fastest-growing-company','ORGANİK Named the 30th Fastest-Growing Company','As a result of the evaluation of more than 500 companies for the 5th TOBB Türkiye 100 competition — held under the leadership of the Union of Chambers and Commodity Exchanges of Türkiye (TOBB) in cooperation with the Economic Policy Research Foundation of Türkiye (TEPAV) — Organik Consulting Services was named the 30th fastest-growing company in the ranking for the 2015-2017 period. At the award ceremony held in Samsun on 19 May 2019, our general manager Sait Sağlam received the award ',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1449','de','organik-als-30-am-schnellsten-wachsendes-unternehmen-ausgezeichnet','ORGANİK als 30. am schnellsten wachsendes Unternehmen ausgezeichnet','Nach der Bewertung von mehr als 500 Unternehmen für den 5. Wettbewerb TOBB Türkiye 100 — durchgeführt unter Führung des türkischen Kammer- und Börsenverbands (TOBB) in Zusammenarbeit mit der Stiftung für Wirtschaftspolitikforschung der Türkei (TEPAV) — wurde Organik Beratungsdienstleistungen in der Rangliste für den Zeitraum 2015-2017 zum 30. am schnellsten wachsenden Unternehmen gekürt. Bei der Preisverleihung am 19. Mai 2019 in Samsun nahm unser Geschäftsführer Sait Sağlam die Auszei',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1448','en','easy-communication-with-difficult-people-training','Easy Communication with Difficult People Training','Making difficulties easier in business life comes through training. On Thursday, 29 November, TİMDER Academy members attended the “Easy Communication with Difficult People” training given by our trainer Dr. Zeynep Hatipoğlu. Hoping to meet again at new trainings.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1448','de','schulung-leichte-kommunikation-mit-schwierigen-menschen','Schulung „Leichte Kommunikation mit schwierigen Menschen“','Schwierigkeiten im Berufsleben leichter zu machen, gelingt durch Schulung. Am Donnerstag, dem 29. November, nahmen die Mitglieder der TİMDER-Akademie an der Schulung „Leichte Kommunikation mit schwierigen Menschen“ von Dr. Zeynep Hatipoğlu teil. Auf ein Wiedersehen bei neuen Schulungen.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1447','en','financial-management-for-non-financiers-training','Financial Management for Non-Financiers Training','The decisions and practices of managers who are not directly connected with financial applications also have financial consequences. For this reason, on Tuesday, 27 November, TİMDER members received the “Financial Management for Non-Financiers” training at TİMDER Academy, given by our trainer Prof. Dr. Burak Arzova.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1447','de','schulung-finanzmanagement-fur-nicht-finanzer','Schulung „Finanzmanagement für Nicht-Finanzer“','Auch die Entscheidungen und Maßnahmen von Führungskräften ohne direkte Verbindung zu Finanzanwendungen haben finanzielle Folgen. Deshalb erhielten die TİMDER-Mitglieder am Dienstag, dem 27. November, in der TİMDER-Akademie die Schulung „Finanzmanagement für Nicht-Finanzer“ von Prof. Dr. Burak Arzova.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1446','en','productivity-and-profit-management-in-dealerships-training','Productivity and Profit Management in Dealerships Training','Sustainable success in dealerships comes through profitability. TİMDER Academy members met at the “Productivity and Profit Management in Dealerships” training, on successful dealer management. The training was given on 15 November by Prof. Dr. Gürbüz Gökçen.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1446','de','schulung-produktivitats-und-gewinnmanagement-in-vertragshandlerschaften','Schulung „Produktivitäts- und Gewinnmanagement in Vertragshändlerschaften“','Nachhaltiger Erfolg im Händlergeschäft führt über die Rentabilität. Die Mitglieder der TİMDER-Akademie trafen sich zur Schulung „Produktivitäts- und Gewinnmanagement in Vertragshändlerschaften“ über erfolgreiches Händlermanagement. Die Schulung wurde am 15. November von Prof. Dr. Gürbüz Gökçen gegeben.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1445','en','management-and-institutionalization-in-family-companies-training','Management and Institutionalization in Family Companies Training','The rise of family companies in the private sector has also brought the concept of institutionalization to the fore. On Tuesday, 13 November, TİMDER Academy members attended the “Management and Institutionalization in Family Companies” training on this important topic, given by Prof. Dr. Fatma Ayanoğlu.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1445','de','schulung-fuhrung-und-institutionalisierung-in-familienunternehmen','Schulung „Führung und Institutionalisierung in Familienunternehmen“','Der Aufstieg der Familienunternehmen in der Privatwirtschaft hat auch den Begriff der Institutionalisierung in den Vordergrund gerückt. Am Dienstag, dem 13. November, nahmen die Mitglieder der TİMDER-Akademie an der Schulung „Führung und Institutionalisierung in Familienunternehmen“ zu diesem wichtigen Thema teil, gegeben von Prof. Dr. Fatma Ayanoğlu.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1444','en','corporate-business-and-risk-management-training','Corporate Business and Risk Management Training','TİMDER Academy members came together on Thursday, 8 November at the “Corporate Business and Risk Management” training given by trainer Prof. Dr. Umut Tuzkaya. Thanks to all attendees.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1444','de','schulung-unternehmensfuhrung-und-risikomanagement','Schulung „Unternehmensführung und Risikomanagement“','Die Mitglieder der TİMDER-Akademie kamen am Donnerstag, dem 8. November, zur Schulung „Unternehmensführung und Risikomanagement“ von Prof. Dr. Umut Tuzkaya zusammen. Dank an alle Teilnehmenden.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1443','en','personal-development-for-collection-skills-training-2','Personal Development for Collection Skills Training','Collection management is one of the areas of business life that requires personal skill. On Tuesday, 6 November, TİMDER members came together at the “Personal Development for Collection Skills” training given by one of our trainers, Dr. Zeki Yüksekbilgili. Thanks to our participants.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1443','de','schulung-personliche-entwicklung-fur-inkassokompetenz-2','Schulung „Persönliche Entwicklung für Inkassokompetenz“','Das Forderungsmanagement gehört zu den Bereichen des Berufslebens, die persönliches Geschick erfordern. Am Dienstag, dem 6. November, kamen die TİMDER-Mitglieder zur Schulung „Persönliche Entwicklung für Inkassokompetenz“ von Dr. Zeki Yüksekbilgili zusammen. Dank an unsere Teilnehmenden.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1442','en','digital-literacy-training','Digital Literacy Training','The way to use digital media effectively is to read it well. TİMDER Academy members received the necessary training on this subject with the “Digital Literacy” training. We thank everyone who attended the training given by our trainer Prof. Dr. İbrahim Kırçova.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1442','de','schulung-digitale-kompetenz','Schulung „Digitale Kompetenz“','Der Weg zur wirksamen Nutzung digitaler Medien führt über ihr gutes Verständnis. Die Mitglieder der TİMDER-Akademie erhielten mit der Schulung „Digitale Kompetenz“ das nötige Rüstzeug. Wir danken allen, die an der Schulung von Prof. Dr. İbrahim Kırçova teilgenommen haben.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1441','en','marketing-in-digital-channels-training','Marketing in Digital Channels Training','In the age we live in, we frequently use digital media. On 30 October, TİMDER Academy members came together at the “Marketing in Digital Channels” training on this very important subject, given by our trainer Yılmaz Bozan. We thank the participants.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1441','de','schulung-marketing-in-digitalen-kanalen','Schulung „Marketing in digitalen Kanälen“','Im heutigen Zeitalter nutzen wir häufig digitale Medien. Am 30. Oktober kamen die Mitglieder der TİMDER-Akademie zur Schulung „Marketing in digitalen Kanälen“ zu diesem sehr wichtigen Thema zusammen, gegeben von unserem Trainer Yılmaz Bozan. Wir danken den Teilnehmenden.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1440','en','communication-training-isbak','Communication Training / İSBAK','Communication is one of the most important topics of business life. To deliver training on this important subject, our trainer Almila Dalkılıç and İSBAK employees came together at the İSBAK head office building on Friday, 26 October. We wish everyone who attended the training successes won through strong communication.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1440','de','kommunikationsschulung-isbak','Kommunikationsschulung / İSBAK','Kommunikation ist eines der wichtigsten Themen des Berufslebens. Für die Schulung zu diesem wichtigen Thema kamen unsere Trainerin Almila Dalkılıç und die Mitarbeitenden von İSBAK am Freitag, dem 26. Oktober, im İSBAK-Hauptgebäude zusammen. Wir wünschen allen Teilnehmenden Erfolge, errungen durch starke Kommunikation.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1439','en','performance-management-and-motivation-training','Performance Management and Motivation Training','TİMDER Academy members received the “Performance Management and Motivation” training from our trainer Dr. Zeynep Hatipoğlu. The training took place on 18 October at the Dedeman Hotel. We thank the participants.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1439','de','schulung-leistungsmanagement-und-motivation','Schulung „Leistungsmanagement und Motivation“','Die Mitglieder der TİMDER-Akademie erhielten die Schulung „Leistungsmanagement und Motivation“ von Dr. Zeynep Hatipoğlu. Die Schulung fand am 18. Oktober im Dedeman Hotel statt. Wir danken den Teilnehmenden.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1438','en','stock-management-at-dealers-training','Stock Management at Dealers Training','TİMDER Academy members came together at the “Stock Management at Dealers” training given by our trainer Dr. Halefşan Sümen. The training was held on Tuesday, 16 October at the Dedeman Hotel. We thank the participants.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1438','de','schulung-bestandsmanagement-bei-handlern','Schulung „Bestandsmanagement bei Händlern“','Die Mitglieder der TİMDER-Akademie kamen zur Schulung „Bestandsmanagement bei Händlern“ von Dr. Halefşan Sümen zusammen. Die Schulung fand am Dienstag, dem 16. Oktober, im Dedeman Hotel statt. Wir danken den Teilnehmenden.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1437','en','employee-happiness-and-motivation-training-timkoder','Employee Happiness and Motivation Training / TİMKODER','TİMKODER members came together at the “Employee Happiness and Motivation — the Key to Success in Business Life” training. Given by our trainer Dr. Gülbeniz Akduman on Friday, 5 October, the training took place at the Association Headquarters in Ankara. We wish you a highly motivated, goal-oriented career.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1437','de','schulung-mitarbeitergluck-und-motivation-timkoder','Schulung „Mitarbeiterglück und Motivation“ / TİMKODER','Die TİMKODER-Mitglieder kamen zur Schulung „Mitarbeiterglück und Motivation — der Schlüssel zum Erfolg im Berufsleben“ zusammen. Die Schulung von Dr. Gülbeniz Akduman fand am Freitag, dem 5. Oktober, im Verbandssitz in Ankara statt. Wir wünschen Ihnen eine hochmotivierte, zielorientierte Karriere.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1436','en','conflict-management-and-problem-solving-techniques-training','Conflict Management and Problem-Solving Techniques Training','This time, TİMDER Academy members came together at the “Conflict Management and Problem-Solving Techniques” training. Given by trainer Gülbeniz Akduman on Thursday, 4 October, the training took place at the Dedeman Hotel.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1436','de','schulung-konfliktmanagement-und-problemlosungstechniken','Schulung „Konfliktmanagement und Problemlösungstechniken“','Diesmal kamen die Mitglieder der TİMDER-Akademie zur Schulung „Konfliktmanagement und Problemlösungstechniken“ zusammen. Die Schulung von Gülbeniz Akduman fand am Donnerstag, dem 4. Oktober, im Dedeman Hotel statt.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1435','en','sales-psychology-and-persuasion-methods','Sales Psychology and Persuasion Methods','TİMDER Academy members met on Tuesday, 2 October for the “Sales Psychology and Persuasion Methods” training. Held at the Dedeman Hotel, the training was given by Hakan Metin Akgün.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1435','de','verkaufspsychologie-und-uberzeugungsmethoden','Verkaufspsychologie und Überzeugungsmethoden','Die Mitglieder der TİMDER-Akademie trafen sich am Dienstag, dem 2. Oktober, zur Schulung „Verkaufspsychologie und Überzeugungsmethoden“. Sie fand im Dedeman Hotel statt und wurde von Hakan Metin Akgün gegeben.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1434','en','life-and-time-management-training','Life and Time Management Training','TİMDER members met at the Istanbul Dedeman Hotel for the “Life and Time Management” training. The training, delivered by our trainer Cemal Bozkurt, attracted intense interest. We thank everyone who attended. Hoping to meet again at new trainings...',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1434','de','schulung-lebens-und-zeitmanagement','Schulung „Lebens- und Zeitmanagement“','Die TİMDER-Mitglieder trafen sich im Dedeman Hotel Istanbul zur Schulung „Lebens- und Zeitmanagement“. Die von unserem Trainer Cemal Bozkurt gegebene Schulung stieß auf großes Interesse. Wir danken allen Teilnehmenden. Auf ein Wiedersehen bei neuen Schulungen...',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1433','en','sales-management-and-sales-techniques-training','Sales Management and Sales Techniques Training','Sales and sales management — one of the most important strategic topics of the business world — has gained more importance than ever, both individually and at company level. Those wishing to develop themselves in this field met on Tuesday, 25 September at the Istanbul Dedeman Hotel within TİMDER Academy. The core title of the training, given by the esteemed trainer Hakan Metin Akgün, was “Sales Management and Sales Techniques”. We wish everyone who attended success, and hope to meet at',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1433','de','schulung-vertriebsmanagement-und-verkaufstechniken','Schulung „Vertriebsmanagement und Verkaufstechniken“','Vertrieb und Vertriebsmanagement — eines der wichtigsten Strategiethemen der Geschäftswelt — hat heute individuell wie auf Unternehmensebene mehr Bedeutung denn je. Wer sich auf diesem Gebiet weiterentwickeln wollte, traf sich am Dienstag, dem 25. September, im Rahmen der TİMDER-Akademie im Dedeman Hotel Istanbul. Der Kerntitel der vom geschätzten Trainer Hakan Metin Akgün gegebenen Schulung lautete „Vertriebsmanagement und Verkaufstechniken“. Wir wünschen allen Teilnehmenden Erfolg un',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1432','en','effective-communication-techniques-training','Effective Communication Techniques Training','Being able to express ourselves correctly, with awareness in communication, provides us many advantages both in business and in social life. For this reason, together with TİMDER Academy, we delivered the “Effective Communication Techniques” training with trainer Sibel Özpulat on 20 September 2018 at the Dedeman Hotel / Gayrettepe.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1432','de','schulung-wirksame-kommunikationstechniken','Schulung „Wirksame Kommunikationstechniken“','Sich mit Bewusstsein in der Kommunikation richtig ausdrücken zu können, verschafft uns im Berufs- wie im Sozialleben viele Vorteile. Deshalb haben wir gemeinsam mit der TİMDER-Akademie am 20. September 2018 im Dedeman Hotel / Gayrettepe die Schulung „Wirksame Kommunikationstechniken“ mit der Trainerin Sibel Özpulat durchgeführt.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1431','en','sales-trends-and-creative-selling-training','Sales Trends and Creative Selling Training','Though they look the same at heart, sales trends are changing at an incredible pace. To keep up with all this, we opened TİMDER Academy\'s 2018 season on Tuesday evening, 18 September at the Dedeman Hotel / Gayrettepe with Dr. Zeki Yüksekbilgili\'s “Sales Trends and Creative Selling” training.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1431','de','schulung-verkaufstrends-und-kreatives-verkaufen','Schulung „Verkaufstrends und kreatives Verkaufen“','Auch wenn sie im Kern gleich erscheinen, ändern sich die Verkaufstrends in unglaublichem Tempo. Um damit Schritt zu halten, eröffneten wir die Saison 2018 der TİMDER-Akademie am Dienstagabend, dem 18. September, im Dedeman Hotel / Gayrettepe mit der Schulung „Verkaufstrends und kreatives Verkaufen“ von Dr. Zeki Yüksekbilgili.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1430','en','employee-motivation-training-burtimder','Employee Motivation Training / BURTİMDER','The training “The Key to Success in Business Life: Employee Motivation”, delivered by trainer Dr. Gülbeniz Akduman at the Bursa Association of Plumbing and Construction Materials Dealers, took place today. Hoping to meet in the new week...',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1430','de','schulung-mitarbeitermotivation-burtimder','Schulung „Mitarbeitermotivation“ / BURTİMDER','Die Schulung „Der Schlüssel zum Erfolg im Berufsleben: Mitarbeitermotivation“ von Dr. Gülbeniz Akduman beim Verband der Sanitär- und Baustoffhändler Bursa fand heute statt. Auf ein Wiedersehen in der neuen Woche...',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1429','en','employee-motivation-training-kontimder','Employee Motivation Training / KONTİMDER','Dr. Gülbeniz Akduman\'s training “The Key to Success: Employee Motivation” took place on 29 March 2018 at the Konya Association of Plumbing and Construction Materials Dealers. We wish you ever more goal-oriented, highly motivated and successful days ahead.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1429','de','schulung-mitarbeitermotivation-kontimder','Schulung „Mitarbeitermotivation“ / KONTİMDER','Die Schulung „Der Schlüssel zum Erfolg: Mitarbeitermotivation“ von Dr. Gülbeniz Akduman fand am 29. März 2018 beim Verband der Sanitär- und Baustoffhändler Konya statt. Wir wünschen stets zielorientiertere, hochmotivierte und erfolgreiche Tage.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1428','en','rhetoric-and-presentation-techniques-training-enerji-as','Rhetoric and Presentation Techniques Training / Enerji AŞ','The first condition of watchable and listenable presentations is rhetoric. The “Rhetoric and Presentation Techniques” training with Dr. Gülbeniz Akduman, which will continue tomorrow as well, is at Enerji AŞ.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1428','de','schulung-rhetorik-und-prasentationstechniken-enerji-as','Schulung „Rhetorik und Präsentationstechniken“ / Enerji AŞ','Die erste Bedingung sehens- und hörenswerter Präsentationen ist die Rhetorik. Die Schulung „Rhetorik und Präsentationstechniken“ mit Dr. Gülbeniz Akduman, die auch morgen weitergeht, findet bei Enerji AŞ statt.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1427','en','financial-literacy-training','Financial Literacy Training','TİMDER Academy / Financial Literacy / Prof. Dr. Burak Arzova',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1427','de','schulung-finanzielle-grundbildung','Schulung „Finanzielle Grundbildung“','TİMDER-Akademie / Finanzielle Grundbildung / Prof. Dr. Burak Arzova',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1426','en','5s-training-imm-service-improvement-directorate','5S Training / IMM Service Improvement Directorate','IMM Service Improvement Directorate / 5S Training / Assoc. Prof. Dr. Ahmet Beşkese',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1426','de','5s-schulung-imm-direktion-fur-serviceverbesserung','5S-Schulung / IMM-Direktion für Serviceverbesserung','IMM-Direktion für Serviceverbesserung / 5S-Schulung / Doç. Dr. Ahmet Beşkese',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1425','en','etiquette-training-metro-ve-guvenlik-as','Etiquette Training / Metro ve Güvenlik AŞ','Metro ve Güvenlik A.Ş. / The end of a 38-day marathon: Etiquette training / Almila Dalkılıç',1);
