INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1405','en','leadership-in-the-new-world-seminar','Leadership in the New World Seminar','With the “Leadership in the New World” seminar, participants were introduced to different leadership models, modern management practices and what must be known for effective leadership.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1405','de','seminar-fuhrung-in-der-neuen-welt','Seminar „Führung in der neuen Welt“','Mit dem Seminar „Führung in der neuen Welt“ wurden den Teilnehmenden verschiedene Führungsmodelle, moderne Managementpraktiken und das nötige Wissen für wirksame Führung vermittelt.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1404','en','private-public-bus-and-iett-trainings','Private Public Bus and İETT Trainings','In cooperation with the Private Public Bus Operators and the İETT General Directorate, we carry out training activities for bus drivers at İETT\'s training centers with our team of expert trainers. The trainings have been defined under the main headings of Traffic Knowledge and Culture, Public Transport Operations in Cities, Public Relations, Human Behavior, Empathy, Psychotechnics, Stress Management and Anger Control.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1404','de','schulungen-fur-private-stadtbusse-und-iett','Schulungen für private Stadtbusse und İETT','In Zusammenarbeit mit den Betreibern privater Stadtbusse und der İETT-Generaldirektion führen wir mit unserem Team fachkundiger Trainer Schulungen für Busfahrer in den Schulungszentren der İETT durch. Die Schulungen umfassen die Hauptthemen Verkehrswissen und -kultur, ÖPNV-Betrieb in Städten, Öffentlichkeitsarbeit, menschliches Verhalten, Empathie, Psychotechnik, Stressbewältigung und Wutkontrolle.',1);
