INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1386','en','transport-academy-iett','Transport Academy / İETT','In cooperation with İETT and the Istanbul Metropolitan Municipality, within the “Transport Academy” project, the “Safe and Defensive Driving Techniques” training was delivered to service drivers. The aim is for the trainings to continue with minibuses and taxis and be delivered to the drivers of all public transport vehicles.',1);
INSERT IGNORE INTO `tablo_url_ceviri` (`UrlID`,`DilKodu`,`Link`,`Title`,`Description`,`YayinDurumu`) VALUES ('1386','de','verkehrsakademie-iett','Verkehrsakademie / İETT','In Zusammenarbeit von İETT und der Stadtverwaltung Istanbul wurde im Rahmen des Projekts „Verkehrsakademie“ die Schulung „Sichere und defensive Fahrtechniken“ für Fahrdienstfahrer durchgeführt. Ziel ist es, die Schulungen mit Minibussen und Taxis fortzusetzen und allen Fahrern öffentlicher Verkehrsmittel anzubieten.',1);
